-- Payload MedQuiz — Prova 4 de Endocrinologia, deduplicado e revisado.
BEGIN;

CREATE OR REPLACE FUNCTION pg_temp.endo_p4_uuid(seed text) RETURNS uuid
LANGUAGE sql IMMUTABLE AS $$
  SELECT (substr(md5(seed),1,8)||'-'||substr(md5(seed),9,4)||'-5'||substr(md5(seed),14,3)||'-a'||substr(md5(seed),18,3)||'-'||substr(md5(seed),21,12))::uuid
$$;

DO $$
DECLARE d uuid; t uuid; qid uuid; q record; a jsonb; letters text[];
BEGIN
  SELECT id INTO d FROM public.disciplines WHERE name='Endocrinologia' LIMIT 1;
  IF d IS NULL THEN RAISE EXCEPTION 'Disciplina Endocrinologia não encontrada'; END IF;
  UPDATE public.questions SET active=false WHERE discipline_id=d AND exam='P4' AND reference='Prova 4 de Endocrinologia — listas consolidadas, deduplicadas e revisadas em 2026.';
  FOR q IN SELECT * FROM jsonb_to_recordset($data$[{"n":1,"topic":"Hipófise — Hipofunção","difficulty":"fácil","statement":"Considere A = hipotálamo, B = adeno-hipófise e C = órgão-alvo. Sabendo que lesões no órgão-alvo são primárias, na hipófise são secundárias e no hipotálamo são terciárias, qual correlação está correta?","correct":["B"],"general":"A classificação acompanha o nível anatômico da falha endócrina: órgão-alvo é primário, hipófise é secundário e hipotálamo é terciário. Logo, A3B2C1.","summary":"Órgão-alvo = primário; hipófise = secundário; hipotálamo = terciário.","memory":"Do periférico para o central: 1 → 2 → 3.","trap":"Não numerar o eixo pela ordem anatômica de cima para baixo.","alts":[{"l":"A","t":"A1, B2, C3","e":"Inverte os extremos: hipotálamo não é primário e a glândula periférica não é terciária."},{"l":"B","t":"A3, B2, C1","e":"hipotálamo = terciário → hipófise = secundário → glândula-alvo = primário."},{"l":"C","t":"A2, B3, C1","e":"Hipófise e hipotálamo estão invertidos. Hipófise = secundário; hipotálamo = terciário."},{"l":"D","t":"A3, B1, C2","e":"Hipotálamo está correto, mas hipófise não é primária e adrenal não é secundária."},{"l":"E","t":"A2, B1, C3","e":"Todas as associações estão incorretas."}],"type":"single"},{"n":2,"topic":"Suprarrenal","difficulty":"médio","statement":"Sobre o hiperaldosteronismo primário, assinale a alternativa correta.","correct":["E"],"general":"As causas mais frequentes são adenoma produtor de aldosterona e hiperplasia adrenal bilateral. Doença unilateral pode ser tratada cirurgicamente; doença bilateral costuma receber antagonista do receptor mineralocorticoide.","summary":"APA e hiperplasia bilateral são as principais etiologias do hiperaldosteronismo primário.","memory":"Unilateral: cirurgia; bilateral: espironolactona ou eplerenona.","trap":"Hipocalemia não está presente em todos os casos.","alts":[{"l":"A","t":"A adrenalectomia total laparoscópica é o tratamento recomendado em pacientes com hiperplasia bilateral de adrenais.","e":"Na hiperplasia adrenal bilateral, o tratamento é medicamentoso com antagonista do receptor mineralocorticoide, principalmente espironolactona (ou eplerenona). A adrenalectomia é indicada principalmente na doença unilateral, como adenoma produtor de aldosterona unilateral."},{"l":"B","t":"A produção aumentada de aldosterona causa retenção de sódio e de potássio que se prolongada e severa pode levar à hipercalemia.","e":"A aldosterona promove retenção de sódio e excreção renal de potássio, portanto pode causar hipocalemia, e não hipercalemia. Também aumenta a excreção de H⁺, podendo produzir alcalose metabólica."},{"l":"C","t":"A maioria dos pacientes com hiperaldosteronismo primário são normotensos","e":"O HAP é uma importante causa de hipertensão arterial secundária. A HAS pode ser resistente, mas muitos pacientes apresentam graus menos intensos de hipertensã"},{"l":"D","t":"O adenoma produtor de aldosterona, em geral, é maligno e apresenta grandes dimensões","e":"O adenoma produtor de aldosterona (adenoma de Conn) é geralmente benigno e pequeno. Carcinoma adrenocortical produtor de aldosterona é raro."},{"l":"E","t":"As duas principais etiologias são o adenoma produtor de aldosterona e a hiperplasia adrenal bilateral","e":"As duas causas mais importantes são a hiperplasia adrenal bilateral e o adenoma produtor de aldosterona. A hiperplasia bilateral é, atualmente, a causa mais frequente."}],"type":"single"},{"n":3,"topic":"Metabolismo ósseo e paratireoide","difficulty":"médio","statement":"Mulher de 70 anos apresenta fratura de quadril, PTH de 542 pg/mL, cálcio de 11,3 mg/dL, fósforo baixo e microcálculos renais. Qual diagnóstico e mecanismo explicam melhor o quadro?","correct":["D"],"general":"Hipercalcemia com PTH inapropriadamente alto e hipofosfatemia aponta para hiperparatireoidismo primário. O PTH aumenta reabsorção tubular de cálcio, fosfatúria, calcitriol e reabsorção óssea mediada por osteoclastos.","summary":"PTH alto com hipercalcemia sugere hiperparatireoidismo primário.","memory":"PTH sobe cálcio e derruba fósforo.","trap":"Na hipercalcemia não mediada por PTH, o PTH deveria estar suprimido.","alts":[{"l":"A","t":"Devido a idade da paciente, o diagnóstico mais provável é de hipercalcemia da malignidade.","e":"Na hipercalcemia da malignidade, o PTH endógeno fica suprimido pelo cálcio elevado. Aqui, o PTH está extremamente elevado (542 pg/mL), indicando hipercalcemia PTH-dependente."},{"l":"B","t":"Diante do importante aumento dos níveis de PTH e cálcio, a maior probabilidade é de estarmos diante de um caso de carcinoma de paratireoide.","e":"PTH muito elevado e hipercalcemia podem levantar suspeita de carcinoma, mas não são suficientes para diagnosticá-lo. O carcinoma de paratireoide é raro e costuma apresentar hipercalcemia mais acentuada, PTH muito elevado e/ou massa cervical. A causa mais comum de HPTP é adenoma benigno de paratireoide."},{"l":"C","t":"A redução dos níveis de fósforo ocorre essencialmente pelo influxo intracelular de fósforo induzido pela hipercalcemia.","e":"O fósforo baixo ocorre porque o PTH reduz a reabsorção de fosfato no túbulo proximal, aumentando sua eliminação urinária (fosfatúria). Não é explicado por influxo intracelular induzido pela hipercalcemia."},{"l":"D","t":"O provável mecanismo da hipercalcemia é hiperatividade osteoclástica induzida pelos altos níveis de PTH, por provável adenoma primário de paratireóides.","e":"O excesso de PTH favorece a reabsorção óssea, indiretamente aumentando a atividade osteoclástica, além de aumentar a reabsorção renal de cálcio e a produção de calcitriol. O resultado pode ser hipercalcemia, perda de massa óssea e nefrolitíase."},{"l":"E","t":"A paciente deve ter como primeira escolha de tratamento o uso de bisfosfonatos.","e":"Em HPTP sintomático, o tratamento definitivo é paratireoidectomia, não bisfosfonato. Esta paciente tem indicações claras de cirurgia, incluindo fratura/osteoporose importante e nefrolitíase."}],"type":"single"},{"n":4,"topic":"Suprarrenal","difficulty":"médio","statement":"Qual situação, isoladamente, NÃO constitui indicação clássica para rastreamento bioquímico da síndrome de Cushing?","correct":["C"],"general":"Rastreia-se Cushing em pacientes com sinais múltiplos e progressivos, manifestações incomuns para a idade, criança com queda de crescimento e ganho de peso e incidentaloma adrenal. Incidentaloma hipofisário isolado não é indicação clássica.","summary":"O rastreamento deve ser dirigido pela probabilidade clínica e pelo incidentaloma adrenal.","memory":"Cushing: progressão, sinais discriminatórios, idade atípica e adrenal incidental.","trap":"O gabarito histórico marcava incidentaloma adrenal, mas diretrizes o incluem entre as indicações.","alts":[{"l":"A","t":"Incidentaloma hipofisário","e":"Pode justificar investigação de hipersecreção hormonal, especialmente se houver características clínicas compatíveis. Adenomas corticotróficos podem produzir ACTH e causar doença de Cushing."},{"l":"B","t":"Pacientes pediátricos com redução da velocidade de crescimento e ganho de peso.","e":"É uma combinação muito sugestiva de hipercortisolismo. Na obesidade simples, a criança geralmente mantém ou aumenta a velocidade de crescimento; no Cushing, ocorre ganho ponderal com desaceleração do crescimento linear."},{"l":"C","t":"Obesidade abdominal associada a hipertensão arterial e Diabetes mellitus.","e":"NÃO é, isoladamente, indicação de rastreamento. São manifestações comuns e inespecíficas. A investigação ganha importância quando existem características mais discriminatórias de hipercortisolismo."},{"l":"D","t":"Características não usuais para a idade (osteoporose coluna, hipertensão arterial).","e":"É indicação de investigação. Osteoporose/fratura em indivíduo jovem ou hipertensão em idade incomum podem ser manifestações de hipercortisolismo secundário."},{"l":"E","t":"Incidentaloma adrenal.","e":"É indicação para avaliar secreção autônoma de cortisol, mesmo que o paciente não apresente os sinais clássicos da síndrome de Cushing."}],"type":"single"},{"n":5,"topic":"Suprarrenal","difficulty":"fácil","statement":"Qual das condições abaixo causa síndrome de Cushing ACTH-independente?","correct":["C"],"general":"Tumores e hiperplasias adrenais podem secretar cortisol autonomamente, suprimindo ACTH. Doença de Cushing e secreção ectópica são ACTH-dependentes.","summary":"Cortisol adrenal autônomo suprime o ACTH.","memory":"Adrenal produz cortisol sozinho: ACTH baixo.","trap":"Doença de Cushing significa adenoma hipofisário produtor de ACTH.","alts":[{"l":"A","t":"O pseudo-cushing.","e":"O pseudo-Cushing é um estado de hipercortisolismo funcional, visto em situações como alcoolismo, depressão grave e obesidade, sem neoplasia adrenal autônoma."},{"l":"B","t":"O tumor carcinóide.","e":"Tumor carcinoide pode produzir ACTH ectópico, causando síndrome de Cushing ACTH-dependente."},{"l":"C","t":"O tumor adrenal.","e":"Tumores adrenais produtores de cortisol secretam cortisol de forma autônoma, levando à supressão do ACTH. Portanto, são causas de Cushing ACTH-independente."},{"l":"D","t":"A doença de Cushing.","e":"A doença de Cushing é causada por adenoma hipofisário produtor de ACTH, logo é ACTH-dependente."},{"l":"E","t":"O carcinoma medular.","e":"Carcinoma medular não é causa típica de síndrome de Cushing ACTH-independente."}],"type":"single"},{"n":6,"topic":"Suprarrenal","difficulty":"médio","statement":"Mulher de 38 anos com feocromocitoma e pressão arterial de 190×105 mmHg será preparada para cirurgia. Qual classe anti-hipertensiva deve ser iniciada primeiro?","correct":["E"],"general":"O preparo começa com bloqueio alfa para controlar vasoconstrição e permitir expansão volêmica. Betabloqueador, se necessário para taquicardia, só deve ser acrescentado após alfa-bloqueio adequado.","summary":"No feocromocitoma, alfa antes de beta.","memory":"Nunca beta primeiro: alfa → volume → beta se necessário.","trap":"Betabloqueio isolado deixa vasoconstrição alfa sem oposição.","alts":[{"l":"A","t":"Diuréticos Tiazídicos.","e":"Tiazídicos não são a primeira escolha, pois não controlam adequadamente os efeitos da descarga catecolaminérgica."},{"l":"B","t":"Antagonistas dos canais de cálcio (Nifedipina).","e":"Bloqueadores de canal de cálcio podem ser usados como adjuvantes, mas não são a terapia clássica inicial."},{"l":"C","t":"Inibidores da enzima conversora da angiotensina (Losartana)","e":"IECA/BRAs não são o tratamento de escolha para o preparo pré-operatório do feocromocitoma."},{"l":"D","t":"Inibidores adrenérgicos (Betabloqueadores)","e":"Betabloqueadores podem ser usados após bloqueio alfa adequado para controlar taquicardia. Nunca devem ser iniciados antes, pois podem causar vasoconstrição alfa desinibida e piora grave da hipertensão."},{"l":"E","t":"Inibidores adrenérgicos (Alfa-1 bloqueadores).","e":"O tratamento inicial é feito com bloqueio alfa-adrenérgico, classicamente com fenoxibenzamina ou alfa-1 bloqueadores como doxazosina, antes da cirurgia."}],"type":"single"},{"n":7,"topic":"Suprarrenal","difficulty":"médio","statement":"Mulher de 19 anos apresenta ganho de peso, estrias violáceas, cortisol livre urinário elevado e ausência de supressão após dexametasona. Qual alternativa está correta?","correct":["C"],"general":"Após confirmar hipercortisolismo, mede-se ACTH para orientar a etiologia. A causa endógena mais comum é doença de Cushing por adenoma hipofisário corticotrófico.","summary":"A doença de Cushing hipofisária é a causa mais comum de Cushing endógeno.","memory":"Endógeno: pense primeiro em ACTH hipofisário.","trap":"Não indicar adrenalectomia antes de localizar e classificar a origem.","alts":[{"l":"A","t":"Pseudo-síndrome de Cushing por depressão é a principal hipótese diagnóstica.","e":"Embora depressão possa causar pseudo-Cushing, esta paciente tem sinais mais específicos de hipercortisolismo, como fraqueza muscular proximal e estrias violáceas, além de testes claramente alterados."},{"l":"B","t":"Adrenalectomia direita está indicada.","e":"Não há informação mostrando tumor adrenal direito. Antes de definir cirurgia, é preciso estabelecer a etiologia do hipercortisolismo."},{"l":"C","t":"A causa mais comum da síndrome de Cushing endógena é o adenoma hipofisário produtor de ACTH.","e":"A causa mais comum de Cushing endógeno é a doença de Cushing, geralmente por adenoma hipofisário secretor de ACTH."},{"l":"D","t":"O cateterismo bilateral dos seios petrosos inferiores é o exame padrão ouro para diferenciar doença de Cushing do estado de pseudo-Cushing.","e":"O cateterismo dos seios petrosos inferiores é usado principalmente para diferenciar fonte hipofisária de ACTH de fonte ectópica, não para diferenciar Cushing verdadeiro de pseudo-Cushing."},{"l":"E","t":"Tumor adrenal é uma causa de Síndrome de Cushing ACTH-dependente.","e":"Tumor adrenal produtor de cortisol causa síndrome de Cushing ACTH-independente, com ACTH suprimido."}],"type":"single"},{"n":8,"topic":"Hipófise — Hiperfunção","difficulty":"fácil","statement":"Alan, 39 anos, apresenta hipertensão, cefaleia, fadiga, artralgia, cirurgia prévia por túnel do carpo, aumento de anel e calçado, redução da libido, sudorese e ronco. Diante da suspeita de acromegalia, qual é o primeiro exame?","correct":["D"],"general":"O IGF-1 ajustado para idade é o melhor teste inicial, pois integra a secreção de GH e não sofre a mesma pulsatilidade do GH aleatório. Resultado elevado ou equívoco requer confirmação apropriada.","summary":"Suspeita de acromegalia começa com IGF-1.","memory":"IGF-1 rastreia; TOTG confirma; RNM localiza.","trap":"Não pedir imagem antes da confirmação bioquímica.","alts":[{"l":"A","t":"Solicitar um teste oral de tolerância à glicose.","e":"O TOTG com dosagem de GH é usado para confirmação quando o IGF-1 está elevado ou o diagnóstico permanece duvidoso. Não é o primeiro exame."},{"l":"B","t":"Solicitar uma ressonância magnética da pituitária.","e":"A RNM de hipófise é feita após confirmação bioquímica, para localizar o adenoma e avaliar extensão tumoral."},{"l":"C","t":"Solicitar um nível de hormônio liberador de GH (GHRH).","e":"A dosagem de GHRH não faz parte da investigação inicial. É reservada para situações raras, como suspeita de produção ectópica."},{"l":"D","t":"Solicitar um nível de IGF-1.","e":"O IGF-1 é o melhor exame inicial de rastreamento da acromegalia, pois reflete a secreção média de GH e varia menos ao longo do dia."},{"l":"E","t":"Solicitar nível de IGFBP3.","e":"O IGFBP-3 não é o exame de escolha para investigação inicial da acromegalia em adultos."}],"type":"single"},{"n":9,"topic":"Hipófise — Hiperfunção","difficulty":"médio","statement":"Mulher de 34 anos apresenta fadiga, ganho de peso, ciclos irregulares, galactorreia, bócio pequeno e pele seca. TSH 72 mUI/L, T4 livre 0,3 ng/dL e prolactina 55 ng/mL, confirmados. Qual é o próximo passo?","correct":["A"],"general":"Hipotireoidismo primário grave aumenta TRH, que estimula prolactina. O tratamento com levotiroxina corrige a causa e frequentemente normaliza a hiperprolactinemia.","summary":"Hipotireoidismo primário pode elevar prolactina por excesso de TRH.","memory":"TSH muito alto + T4L baixo + PRL moderada: trate a tireoide.","trap":"Não diagnosticar prolactinoma antes de corrigir causa secundária evidente.","alts":[{"l":"A","t":"Iniciar terapia levotiroxina.","e":"A paciente tem hipotireoidismo primário franco: TSH muito elevado e T4 livre baixo. O aumento de TRH estimula também a secreção de prolactina, explicando a hiperprolactinemia. O tratamento é corrigir o hipotireoidismo com levotiroxina."},{"l":"B","t":"Obter uma ressonância magnética da hipófise.","e":"A RNM de hipófise não é o primeiro passo quando há uma causa evidente de hiperprolactinemia. Deve-se tratar primeiro o hipotireoidismo e reavaliar a prolactina."},{"l":"C","t":"Iniciar a terapia com estrogênio.","e":"Estrogênio não trata a causa do problema e pode, inclusive, aumentar a prolactina."},{"l":"D","t":"Iniciar a terapia agonista da dopamina.","e":"Agonista dopaminérgico, como cabergolina, é indicado principalmente em prolactinoma. Aqui, a causa mais provável é o hipotireoidismo."},{"l":"E","t":"Colher nova prolactina sérica.","e":"A prolactina já foi repetida e permaneceu elevada. O próximo passo é tratar a causa identificada, não repetir novamente o exame."}],"type":"single"},{"n":10,"topic":"Hipófise — Hiperfunção","difficulty":"fácil","statement":"Sobre as causas de hiperprolactinemia, assinale a alternativa correta.","correct":["D"],"general":"Prolactinoma é o adenoma hipofisário funcionante mais frequente. Antes de diagnosticá-lo, excluem-se gestação, fármacos, hipotireoidismo, doença renal/hepática e macroprolactina conforme o contexto.","summary":"Prolactinoma é o adenoma hipofisário funcionante mais comum.","memory":"PRL: gestação, remédios, tireoide, rim/fígado, macroprolactina e prolactinoma.","trap":"No hipotireoidismo primário, o TRH aumenta.","alts":[{"l":"A","t":"A cirrose hepática causa hiperprolactinemia por provocar aumento da depuração renal do hormônio.","e":"A cirrose pode causar hiperprolactinemia por redução da depuração/metabolização da prolactina, e não por aumento da depuração renal."},{"l":"B","t":"O aumento da macroprolactina é a responsável por mais de 90% dos casos de hiperprolactinemia em homens.","e":"A macroprolactina pode causar elevação laboratorial da PRL com pouca repercussão clínica, mas não responde por >90% dos casos em homens."},{"l":"C","t":"A produção ectópica de PRL por tumores extra hipofisários é a causa patológica mais frequente de hiperprolactinemia.","e":"Produção ectópica de PRL é rara. A causa patológica hipofisária mais frequente é o prolactinoma."},{"l":"D","t":"O prolactinoma representa o adenoma funcionante hipofisário mais frequente.","e":"O prolactinoma é o adenoma hipofisário funcionante mais comum e causa hiperprolactinemia por secreção autônoma de PRL."},{"l":"E","t":"O hipotireoidismo primário pode ser causa de hiperprolactinemia, a qual é provocada pela diminuição do hormônio liberador de tireotrofina (TRH).","e":"No hipotireoidismo primário há aumento de TRH, que pode estimular a secreção de prolactina. A alternativa erra ao dizer que o TRH diminui."}],"type":"single"},{"n":11,"topic":"Hipófise — Hipofunção","difficulty":"difícil","statement":"JVCJ, 42 anos, com queda de libido, apresenta aumento difuso da hipófise e espessamento da haste, sugerindo hipofisite linfocítica. Qual alternativa integra corretamente diagnóstico e reposição?","correct":["E"],"general":"Hipofisite pode causar déficits centrais de eixos gonadal, tireoidiano e adrenal. A insuficiência adrenal deve ser tratada antes de iniciar levotiroxina para evitar crise adrenal.","summary":"Hipofisite pode causar hipopituitarismo combinado; glicocorticoide vem antes de T4.","memory":"No hipopituitarismo: cortisol primeiro, tireoide depois.","trap":"Não repor levotiroxina antes de proteger o eixo adrenal.","alts":[{"l":"A","t":"Hipogonadismo Hipergonadotrófico, Hipotireoidismo Central secundário à Hipofisite Linfocítica. Reposição de testosterona apenas.","e":"A testosterona está baixa com LH e FSH baixos/inadequadamente normais, caracterizando hipogonadismo hipogonadotrófico, e não hipergonadotrófico. Além disso, há também insuficiência adrenal central, então testosterona isoladamente não basta."},{"l":"B","t":"Insuficiência adrenal central secundária à tumor hipofisário. Tratamento cirúrgico e reposição de glicocorticóide.","e":"O quadro sugere hipofisite linfocítica, não tumor hipofisário clássico. A RNM mostra aumento difuso da hipófise e espessamento da haste, achados compatíveis com processo inflamatório."},{"l":"C","t":"Hipogonadismo Hipogonadotrófico, Hipertireoidismo e Insuficiência adrenal central secundária à Hipofisite Linfocítica. Reposição de testosterona e glicocorticóide.","e":"O paciente tem hipotireoidismo central, não hipertireoidismo: T4 livre está baixo com TSH inadequadamente normal. O restante da descrição se aproxima do diagnóstico."},{"l":"D","t":"Hipogonadismo Hipogonadotrófico, Hipotireoidismo e Insuficiência adrenal centrais secundários ao diabetes mellitus tipo 2. Não há necessidade de terapia de reposição hormonal.","e":"Diabetes mellitus tipo 2 não explica esse conjunto de déficits hipofisários múltiplos nem o espessamento da haste. Há necessidade de reposição hormonal."},{"l":"E","t":"Hipogonadismo Hipogonadotrófico, Hipotireoidismo e Insuficiência adrenal centrais devido a Hipofisite Linfocítica. Reposição de testosterona, glicocorticóide e levotiroxina.","e":"O paciente apresenta:\nHipogonadismo hipogonadotrófico: testosterona ↓ com LH/FSH baixos ou inadequadamente normais.\nHipotireoidismo central: T4L ↓ com TSH inadequadamente normal.\nInsuficiência adrenal central: cortisol ↓ com ACTH baixo.\nRNM compatível com hipofisite linfocítica."}],"type":"single"},{"n":12,"topic":"Hipófise — Hipofunção","difficulty":"fácil","statement":"Criança de 10 anos, após cirurgia de tumor hipofisário, evolui com suspeita de diabetes insípido central. Qual achado é esperado?","correct":["E"],"general":"Deficiência de ADH reduz a reabsorção de água nos ductos coletores, causando grande volume de urina diluída, polidipsia e tendência a hipernatremia se a reposição hídrica for insuficiente.","summary":"Diabetes insípido central causa poliúria hipotônica.","memory":"Sem ADH: perde água livre.","trap":"DI tende a hipernatremia, não hiponatremia.","alts":[{"l":"A","t":"Pouco ADH (hormônio antidiurético), o que aumenta a reabsorção de água","e":"Há pouco ADH, mas isso reduz a reabsorção de água no túbulo coletor."},{"l":"B","t":"Osmolalidade urinária inapropriadamente elevada","e":"No diabetes insípido, a urina é muito diluída, portanto a osmolalidade urinária é baixa."},{"l":"C","t":"Sódio urinário elevado","e":"Não é o achado característico principal. O problema central é a perda de água livre."},{"l":"D","t":"Hiponatremia","e":"O mais típico é hipernatremia, especialmente se a reposição hídrica for inadequada."},{"l":"E","t":"Poliúria","e":"A deficiência de ADH reduz a reabsorção de água, levando a grande volume de urina diluída."}],"type":"single"},{"n":13,"topic":"Metabolismo ósseo e paratireoide","difficulty":"fácil","statement":"Qual alternativa identifica corretamente uma célula responsável pela formação da matriz óssea?","correct":["D"],"general":"Osteoblastos, derivados de células mesenquimais, sintetizam osteoide e promovem mineralização. Osteoclastos são hematopoiéticos e reabsorvem osso; osteócitos derivam de osteoblastos.","summary":"Osteoblasto forma; osteoclasto reabsorve; osteócito mantém.","memory":"Blasto constrói, clasto quebra.","trap":"O osteócito é o estágio maduro do osteoblasto.","alts":[{"l":"A","t":"O osteócito é o estágio final de diferenciação do osteoclasto","e":"O osteócito é o estágio final de diferenciação do osteoblasto, não do osteoclasto."},{"l":"B","t":"Os osteoclastos são responsáveis pela síntese de matriz óssea","e":"Quem sintetiza a matriz óssea é o osteoblasto. O osteoclasto faz reabsorção óssea."},{"l":"C","t":"Os osteoblastos são originários do sistema hematopoiético, como os monócitos e macrófagos.","e":"Os osteoclastos é que derivam da linhagem hematopoiética/monócito-macrófago. Os osteoblastos derivam de células mesenquimais."},{"l":"D","t":"O metabolismo ósseo é acoplado, ou seja, ocorre formação nos locais onde houve reabsorção prévia","e":"O remodelamento ósseo é acoplado: primeiro ocorre reabsorção pelo osteoclasto e, em seguida, formação óssea pelo osteoblasto no mesmo local."},{"l":"E","t":"Os osteoblastos são células responsáveis pela formação óssea","e":"⚠️ Conceitualmente verdadeira. Os osteoblastos realmente são responsáveis pela formação óssea. Porém, se a questão exige apenas uma alternativa, há provável erro de elaboração, porque D e E estão corretas."}],"type":"single"},{"n":14,"topic":"Hipófise — Hipofunção","difficulty":"médio","statement":"Sobre hipopituitarismo, assinale a alternativa INCORRETA.","correct":["B"],"general":"O quadro depende da causa, velocidade e extensão. Em lesões compressivas, GH e gonadotrofinas costumam ser perdidos antes; TSH e ACTH geralmente são preservados até fases posteriores.","summary":"GH e LH/FSH tendem a falhar antes de TSH e ACTH.","memory":"Ordem típica: GH → gonadotrofinas → TSH → ACTH.","trap":"ACTH e TSH são vitais, mas não costumam ser os primeiros eixos perdidos.","alts":[{"l":"A","t":"O quadro clínico e as complicações do hipopituitarismo dependem da etiologia, do tipo e da gravidade da insuficiência hormonal.","e":"A apresentação do hipopituitarismo varia conforme causa, velocidade de instalação, número de eixos acometidos e intensidade da deficiência hormonal."},{"l":"B","t":"Os eixos do ACTH e TSH são os primeiros afetados por lesões tumorais intra selares.","e":"Em lesões expansivas hipofisárias, os eixos mais sensíveis costumam ser GH e gonadotrofinas (LH/FSH). ACTH e TSH geralmente são comprometidos mais tardiamente."},{"l":"C","t":"Tumores hipofisários e seu tratamento (cirurgia ou radioterapia) são as principais causas.","e":"Tumores hipofisários e seu tratamento por cirurgia ou radioterapia estão entre as causas adquiridas mais comuns de hipopituitarismo."},{"l":"D","t":"Mutações de fatores de transcrição como PIT 1 e PROP-1 podem causar várias deficiências associadas como GH, prolactina e TSH no mesmo paciente.","e":"Mutações em fatores de transcrição como PIT-1 e PROP-1 podem causar deficiência combinada de vários hormônios hipofisários."},{"l":"E","t":"Síndrome de Sheehan caracteriza-se pelo hipopituitarismo por necrose da glândula pituitária decorrente de uma complicação hemorrágica pós-parto.","e":"A síndrome de Sheehan decorre de necrose isquêmica da hipófise após hemorragia obstétrica importante, levando a hipopituitarismo."}],"type":"single"},{"n":15,"topic":"Hipófise — Hiperfunção","difficulty":"médio","statement":"Mulher de 47 anos apresenta aumento de extremidades, macroglossia, prognatismo, hipertensão e diabetes. Sobre acromegalia, assinale a alternativa INCORRETA.","correct":["E"],"general":"Acromegalia quase sempre decorre de adenoma somatotrófico hipofisário. IGF-1 é o teste inicial, TOTG com GH confirma quando necessário, RNM localiza e cirurgia transesfenoidal é primeira escolha para a maioria dos tumores ressecáveis.","summary":"Acromegalia usualmente é adenoma hipofisário secretor de GH.","memory":"IGF-1 → TOTG → RNM → transesfenoidal.","trap":"Hipersecreção hipotalâmica de GHRH é causa excepcional.","alts":[{"l":"A","t":"As complicações cardiovasculares são as primeiras causas de mortalidade nos pacientes com acromegalia.","e":"Complicações cardiovasculares estão entre as principais causas de mortalidade na acromegalia, especialmente HAS, cardiomiopatia e doença cardiovascular."},{"l":"B","t":"Nos pacientes em que o diagnóstico não pode ser descartado ou confirmado com as dosagens basais de GH e IGF-1, está indicada a dosagem do GH durante teste oral de tolerância à glicose.","e":"Quando GH e IGF-1 basais não esclarecem o diagnóstico, realiza-se TOTG com dosagem de GH. Na acromegalia, o GH não suprime adequadamente após a glicose."},{"l":"C","t":"A cirurgia é considerada a terapia de primeira escolha no tratamento da acromegalia e na maioria dos casos realizada por via transesfenoidal.","e":"A cirurgia transesfenoidal é o tratamento de primeira escolha na maioria dos adenomas hipofisários ressecáveis associados à acromegalia."},{"l":"D","t":"Geralmente a ressonância nuclear magnética (RNM) de sela túrcica evidencia um macrodenoma hipofisário.","e":"A maioria dos pacientes é diagnosticada tardiamente e apresenta macroadenoma hipofisário na RNM."},{"l":"E","t":"O principal mecanismo envolvido na gênese dos sintomas da acromegalia é a hipersecreção de GHRH (growth-hormone releasing hormone GHRH) hipotalâmico","e":"O principal mecanismo é a hipersecreção de GH por adenoma hipofisário, com aumento secundário de IGF-1. Hipersecreção de GHRH é causa rara."}],"type":"single"},{"n":16,"topic":"Hipófise — Hiperfunção","difficulty":"médio","statement":"Mulher de 24 anos apresenta amenorreia e hiperprolactinemia. Assinale a alternativa INCORRETA.","correct":["A"],"general":"A intensidade da elevação ajuda na etiologia: valores muito altos favorecem prolactinoma, embora haja sobreposição e efeito gancho em macroadenomas. Sempre se investigam sintomas, fármacos, gestação, tireoide, rim e fígado.","summary":"Quanto maior a prolactina, maior a suspeita de prolactinoma, com exceções.","memory":"PRL muito alta aponta para prolactinoma; confirme contexto e diluição se necessário.","trap":"Fármacos geralmente causam elevações moderadas, não as maiores concentrações.","alts":[{"l":"A","t":"A magnitude da elevação nos níveis séricos de prolactina é útil na determinação da etiologia, uma vez que os valores mais altos são encontrados em pacientes com hiperprolactinemia farmacológica.","e":"A magnitude da prolactina ajuda na etiologia, mas os valores mais altos costumam ocorrer nos prolactinomas, especialmente macroprolactinomas, e não na forma farmacológica."},{"l":"B","t":"O uso de alguns medicamentos psicoativos pode estar associado à hiperprolactinemia de etiologia farmacológica.","e":"Alguns psicoativos, principalmente antipsicóticos, bloqueiam a ação da dopamina e podem elevar a prolactina."},{"l":"C","t":"A hiperprolactinemia patológica pode ser causada insuficiência renal e hepática, hipotireoidismo, desconexão de haste hipofisária e prolactinoma.","e":"Insuficiência renal/hepática, hipotireoidismo, lesões da haste hipofisária e prolactinoma são causas reconhecidas de hiperprolactinemia."},{"l":"D","t":"A hiperprolactinemia deve ser investigada em mulheres frente à ocorrência de queixas como amenorreia/irregularidade menstrual, galactorreia e infertilidade.","e":"Amenorreia, irregularidade menstrual, galactorreia e infertilidade são manifestações típicas e justificam investigação de prolactina."},{"l":"E","t":"A hiperprolactinemia pode ser vista em pacientes com hipotireoidismo primário descompensado, devido sobretudo ao aumento do TRH (que estimula a síntese de prolactina).","e":"No hipotireoidismo primário, há TRH aumentado, que estimula tanto TSH quanto prolactina."}],"type":"single"},{"n":17,"topic":"Metabolismo ósseo e paratireoide","difficulty":"médio","statement":"Mulher de 63 anos, com embolia pulmonar prévia, diabetes, hipertensão, fratura de colo de fêmur e T-scores de -4,8 na coluna e -2,9 no fêmur, necessita tratamento para osteoporose. Assinale a alternativa correta.","correct":["E"],"general":"Fratura de quadril e T-score ≤-2,5 estabelecem alto ou muito alto risco. Bisfosfonatos são opção de primeira linha em muitos pacientes por reduzirem reabsorção osteoclástica; risco muito alto pode exigir avaliação de terapia anabólica.","summary":"Bisfosfonatos reduzem reabsorção óssea e são primeira linha frequente.","memory":"Fratura de quadril já indica tratamento, independentemente do T-score.","trap":"Radiografia não substitui densitometria para medir massa óssea.","alts":[{"l":"A","t":"A osteoporose é uma doença silenciosa que afeta especialmente os adultos jovens e tem elevada taxa de morbimortalidade.","e":"A osteoporose é realmente uma doença muitas vezes silenciosa e com alta morbimortalidade, mas acomete principalmente mulheres pós-menopausa e idosos, não adultos jovens."},{"l":"B","t":"O exame mais adequado para o diagnóstico da Osteoporose é a radiografia, que permite avaliar o estágio da doença e serve como método de acompanhamento do tratamento.","e":"O exame de escolha para diagnóstico e acompanhamento é a densitometria óssea (DXA), e não a radiografia simples. A radiografia detecta perda óssea mais tardiamente."},{"l":"C","t":"A vitamina D é importante no tratamento da osteoporose. As principais fontes na dieta são o leite e os seus derivados.","e":"A vitamina D é importante, mas suas principais fontes não são leite e derivados. A principal fonte é a síntese cutânea pela exposição solar, além de alguns alimentos específicos (óleos,peixes gordurosos, gema de ovo, fígado)."},{"l":"D","t":"Alguns fatores de risco importantes relacionados à osteoporose e a fraturas na pós-menopausa são: idade, etnia branca ou oriental, história prévia pessoal e familiar de fratura, obesidade, tabagismo, ingestão abusiva de bebidas alcoólicas e atividade física aeróbica.","e":"Idade, etnia branca/oriental, história de fratura, tabagismo e álcool aumentam risco, mas obesidade e atividade física aeróbica não são fatores de risco clássicos; em geral, baixo peso e sedentarismo aumentam o risco."},{"l":"E","t":"Os bisfosfonatos são a classe de drogas considerada de primeira linha para o tratamento da osteoporose na pós-menopausa e agem inibindo a atividade dos osteoclastos.","e":"Os bisfosfonatos são drogas de primeira linha em muitos casos de osteoporose pós-menopausa e atuam inibindo os osteoclastos, reduzindo a reabsorção óssea."}],"type":"single"},{"n":18,"topic":"Hipófise — Hiperfunção","difficulty":"médio","statement":"Bloco 1 — Hipófise — Hiperfunção. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:F","B:F","C:V","D:F","E:V"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"A prolactina é um hormônio produzido pelas células somatotróficas da hipófise anterior","e":"Falsa. A prolactina é produzida pelas células lactotróficas da adeno-hipófise. As células somatotróficas produzem GH."},{"l":"B","t":"Pela idade e por ser nulípara, a gestação pode ser descartada do possível diagnóstico dessa paciente.","e":"Falsa. Gestação sempre deve ser excluída em mulher em idade fértil com galactorreia/amenorreia, independentemente de idade ou nuliparidade."},{"l":"C","t":"Os agonistas dopaminérgicos como a cabergolina, ligam-se aos receptores D2 nos lactotrofos inibindo a síntese de prolactina","e":"Verdadeira. Agonistas dopaminérgicos, como cabergolina, atuam nos receptores D2 dos lactotrofos, reduzindo síntese e secreção de prolactina."},{"l":"D","t":"Caso seja um tumor hipofisário, o diagnóstico mais provável é macroprolactinoma","e":"Falsa. Se houver prolactinoma, não é obrigatório que seja macroprolactinoma. Microprolactinomas são frequentes em mulheres e muitas vezes se apresentam com galactorreia e alterações menstruais."},{"l":"E","t":"Lesões que causam compressão em haste hipofisária podem causar hiperprolactinemia por impedir a chegada de dopamina para a hipófise","e":"Verdadeira. Compressão da haste reduz a chegada de dopamina à hipófise. Como a dopamina normalmente inibe a prolactina, sua redução leva a hiperprolactinemia por efeito de haste."}],"type":"true_false"},{"n":19,"topic":"Hipófise — Hiperfunção","difficulty":"médio","statement":"Avalie o caso clínico e responda as questões a seguir: Homem de 55 anos, hipertenso, é avaliado com queixa crônica de fraqueza e dores articulares. Refere também alteração de glicemia capilar em exame realizado na UBS. Relata que seu anel de casamento não cabe mais no seu dedo e perdeu vários pares de sapatos nos últimos 5 anos devido ao crescimento do seu pé. Ao exame físico foi observado prognatismo, aumento de nariz e lábios. Foi feita a suspeita clínica de acromegalia. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:V","B:V","C:F","D:F"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"A dosagem de GH basal não é um bom exame para confirmação do diagnóstico uma vez que a secreção do GH é pulsátil.","e":"Verdadeira. O GH basal isolado não é bom exame confirmatório porque sua secreção é pulsátil e varia ao longo do dia."},{"l":"B","t":"As complicações sistêmicas resultam em elevada morbi-mortalidade e redução da expectativa de vida","e":"Verdadeira. A acromegalia aumenta morbimortalidade por complicações principalmente cardiovasculares, respiratórias e metabólicas.\nPacientes com acromegalia podem ter outras alterações endócrinas e metabólicas como: diabetes, ganho de peso, hiperinsulinemia e hipertensão."},{"l":"C","t":"Crescimento linear exagerado e gigantismo são vistos na maioria dos pacientes adultos com tumores secretores de GH.","e":"Falsa. Crescimento linear exagerado ocorre quando o excesso de GH surge antes do fechamento das cartilagens de crescimento, causando gigantismo. No adulto ocorre acromegalia, com aumento de extremidades e partes moles, sem aumento da altura.\nA cirurgia com abordagem transcraniana é o tratamento de primeira escolha na maioria dos casos. Como alternativa, pode ser feita a via transesfenoidal, pois esta tem altas taxas de complicações."},{"l":"D","t":"A cirurgia com abordagem transcraniana é o tratamento de primeira escolha na maioria dos casos. Como alternativa, pode ser feita a via transesfenoidal, pois esta tem altas taxas de complicações.","e":"Falsa. A abordagem cirúrgica de escolha é geralmente a transesfenoidal. A via transcraniana é reservada para casos selecionados e costuma ser mais invasiva."}],"type":"true_false"},{"n":20,"topic":"Hipófise — Hiperfunção","difficulty":"médio","statement":"Bloco 3 — Hipófise — Hiperfunção. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:V","B:V","C:V","D:V","E:V"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"A magnitude da elevação nos níveis séricos de prolactina é útil na determinação da etiologia, uma vez que os valores mais altos são encontrados em pacientes com hiperprolactinemia por prolactinomas.","e":"Verdadeiro. Prolactinomas, especialmente os macroprolactinomas, costumam produzir níveis mais elevados de prolactina. A intensidade da elevação ajuda na investigação etiológica."},{"l":"B","t":"O uso de alguns medicamentos psicoativos pode estar associado à hiperprolactinemia de etiologia farmacológica.","e":"Verdadeiro. Antipsicóticos e outros fármacos que reduzem a ação dopaminérgica podem elevar a prolactina, pois a dopamina normalmente inibe sua secreção."},{"l":"C","t":"A hiperprolactinemia patológica pode ser causada por insuficiência renal e hepática.","e":"Verdadeiro. Doenças renal e hepática podem reduzir a depuração/metabolização da prolactina, levando ao aumento de seus níveis séricos."},{"l":"D","t":"A hiperprolactinemia deve ser investigada em mulheres frente à ocorrência de queixas como amenorreia/irregularidade menstrual, galactorreia e infertilidade.","e":"Verdadeiro. A prolactina elevada inibe o eixo GnRH → LH/FSH, podendo causar hipogonadismo, amenorreia, infertilidade e galactorreia."},{"l":"E","t":"A hiperprolactinemia pode ser vista em pacientes com hipotireoidismo primário descompensado, devido sobretudo ao aumento do TRH (que estimula a síntese de prolactina).","e":"Verdadeiro. No hipotireoidismo primário, há T4 ↓ → TRH ↑ e TSH ↑; o TRH também estimula os lactotrofos, podendo elevar a prolactina."}],"type":"true_false"},{"n":21,"topic":"Suprarrenal","difficulty":"médio","statement":"Bloco 4 — Suprarrenal. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:F","B:F","C:F","D:V","E:F"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"O tratamento substitutivo visa administrar os próprios hormônios hipofisários","e":"Falsa. O tratamento não costuma repor os hormônios hipofisários em si, mas os hormônios finais das glândulas-alvo, como glicocorticoide, levotiroxina e hormônios sexuais.\nA redução ou a ausência de lactação é o último sinal clínico a aparecer"},{"l":"B","t":"A redução ou a ausência de lactação é o último sinal clínico a aparecer","e":"Falsa. A falha na lactação pode ser um dos primeiros sinais, por deficiência de prolactina após necrose hipofisária.\nA tomografia de crânio é de grande ajuda no diagnóstico"},{"l":"C","t":"A tomografia de crânio é de grande ajuda no diagnóstico","e":"Falsa. A RNM de sela túrcica é mais útil que a TC para avaliação da hipófise. Com o tempo, pode haver aspecto de sela vazia.\nNão devemos administrar hormônio tireoidiano precocemente se houver suspeita de insuficiência adrenal"},{"l":"D","t":"Não devemos administrar hormônio tireoidiano precocemente se houver suspeita de insuficiência adrenal","e":"Verdadeira. Se houver suspeita de insuficiência adrenal, deve-se repor glicocorticoide antes da levotiroxina, pois o hormônio tireoidiano pode precipitar crise adrenal.\nA melhor conduta é a expectante, não há necessidade de reposição hormonal."},{"l":"E","t":"A melhor conduta é a expectante, não há necessidade de reposição hormonal.","e":"Falsa. O tratamento é reposição hormonal, não conduta expectante."}],"type":"true_false"},{"n":22,"topic":"Suprarrenal","difficulty":"médio","statement":"Bloco 5 — Suprarrenal. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:V","B:F","C:V","D:F","E:V"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"Por definição, a doença de Cushing resulta de um adenoma hipofisário.","e":"Verdadeira. Doença de Cushing é, por definição, o hipercortisolismo causado por adenoma hipofisário secretor de ACTH.\nPor definição, a doença de Cushing resulta de um adenoma cortical adrenal."},{"l":"B","t":"Por definição, a doença de Cushing resulta de um adenoma cortical adrenal.","e":"Falsa. Adenoma cortical adrenal causa síndrome de Cushing ACTH-independente, e não doença de Cushing.\nA administração de glicocorticóides é causa de Síndrome de Cushing."},{"l":"C","t":"A administração de glicocorticóides é causa de Síndrome de Cushing.","e":"Verdadeira. O uso crônico de glicocorticoides exógenos é a causa mais comum de síndrome de Cushing.\nTodas as causas de hiperadrenocorticismo são de origem adrenal."},{"l":"D","t":"Todas as causas de hiperadrenocorticismo são de origem adrenal.","e":"Falsa. Nem todas as causas são adrenais. Podem ser:\nhipofisárias;\nectópicas;\nadrenais;\niatrogênicas por corticoide.\nO teste de supressão com dexametasona é um bom teste para investigar a Síndrome de Cushing"},{"l":"E","t":"O teste de supressão com dexametasona é um bom teste para investigar a Síndrome de Cushing","e":"Verdadeira. O teste de supressão com dexametasona é utilizado na investigação do hipercortisolismo. Em indivíduos normais, a dexametasona suprime o cortisol; na síndrome de Cushing, essa supressão é inadequada."}],"type":"true_false"},{"n":23,"topic":"Suprarrenal","difficulty":"médio","statement":"Bloco 6 — Suprarrenal. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:F","B:V","C:V","D:V","E:F"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"Independentemente da causa, o paciente com doença de Addison tende a apresentar hipercalcemia","e":"Falsa. A doença de Addison não se caracteriza por hipercalcemia obrigatória. Pode ocorrer hipercalcemia em alguns casos, mas não é um achado típico ou constante.\nIndependentemente da causa, o paciente com doença de Addison tende a apresentar hipercalemia"},{"l":"B","t":"Independentemente da causa, o paciente com doença de Addison tende a apresentar hipercalemia","e":"Verdadeira. Na insuficiência adrenal primária há deficiência de aldosterona, levando a menor excreção renal de potássio → hipercalemia.\nNa doença de Addison o déficit de volume pode ser severo e a hipotensão e o choque podem não responder aos vasopressores a menos que sejam administrados glicocorticóides"},{"l":"C","t":"Na doença de Addison o déficit de volume pode ser severo e a hipotensão e o choque podem não responder aos vasopressores a menos que sejam administrados glicocorticóides","e":"Verdadeira. Na crise adrenal pode haver hipovolemia e hipotensão graves. A resposta aos vasopressores pode ser inadequada enquanto não houver reposição de glicocorticoide, geralmente hidrocortisona.\nO procedimento padrão mais adequado para detectar feocromocitoma é a dosagem de metanefrinas urinárias."},{"l":"D","t":"O procedimento padrão mais adequado para detectar feocromocitoma é a dosagem de metanefrinas urinárias.","e":"Verdadeira no contexto da prova. A investigação bioquímica do feocromocitoma pode ser feita com metanefrinas urinárias fracionadas de 24 h. Atualmente, tanto elas quanto as metanefrinas plasmáticas livres são testes iniciais recomendados.\nNíveis baixos de hormônios do córtex adrenal resultam em bócio"},{"l":"E","t":"Níveis baixos de hormônios do córtex adrenal resultam em bócio","e":"Falsa. A deficiência de hormônios do córtex adrenal não causa bócio. Bócio está relacionado principalmente a alterações da tireoide/TSH."}],"type":"true_false"},{"n":24,"topic":"Metabolismo ósseo e paratireoide","difficulty":"médio","statement":"Bloco 7 — Metabolismo ósseo e paratireoide. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:V","B:V","C:V","D:F","E:V"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"Não se deve retirar o cálcio alimentar da dieta do paciente com hiperparatireoidismo","e":"Verdadeira. Não se recomenda retirar cálcio da dieta no hiperparatireoidismo. A ingestão adequada de cálcio deve ser mantida; restrição excessiva pode até aumentar a secreção de PTH.\nHipoparatireoidismo é doença rara, mas pode ter complicações graves"},{"l":"B","t":"Hipoparatireoidismo é doença rara, mas pode ter complicações graves","e":"Verdadeira. O hipoparatireoidismo é relativamente raro, mas pode causar hipocalcemia grave, tetania, convulsões e arritmias.\nA principal causa do hipoparatireoidismo é por complicações cirúrgicas"},{"l":"C","t":"A principal causa do hipoparatireoidismo é por complicações cirúrgicas","e":"Verdadeira. A causa mais comum é pós-cirúrgica, especialmente após tireoidectomia ou cirurgia cervical, por remoção ou lesão das paratireoides.\nO tratamento do hipoparatireoidismo é feito com reposição de PTH"},{"l":"D","t":"O tratamento do hipoparatireoidismo é feito com reposição de PTH","e":"Falsa. O tratamento convencional é feito com reposição de cálcio e vitamina D ativa (calcitriol). A reposição de PTH não é a terapia habitual de primeira linha e fica reservada para situações selecionadas.\nO pseudohipoparatireoidismo apresenta níveis elevados de PTH sérico"},{"l":"E","t":"O pseudohipoparatireoidismo apresenta níveis elevados de PTH sérico","e":"Verdadeira. No pseudohipoparatireoidismo, há resistência dos tecidos à ação do PTH. Assim, o organismo tenta compensar produzindo mais PTH → PTH elevado, com tendência a cálcio baixo e fósforo alto."}],"type":"true_false"},{"n":25,"topic":"Metabolismo ósseo e paratireoide","difficulty":"médio","statement":"Bloco 8 — Metabolismo ósseo e paratireoide. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:V","B:V","C:F","D:F","E:V"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"A osteoporose é uma doença caracterizada pela fragilidade óssea e alterações na sua microarquitetura","e":"Verdadeira. A osteoporose é caracterizada por redução da resistência óssea, com baixa massa óssea e deterioração da microarquitetura, aumentando o risco de fraturas.\nO tabagismo pode acarretar diminuição de massa óssea e maior risco de fraturas sobretudo com o avançar da idade"},{"l":"B","t":"O tabagismo pode acarretar diminuição de massa óssea e maior risco de fraturas sobretudo com o avançar da idade","e":"Verdadeira. O tabagismo acelera a perda de massa óssea e aumenta o risco de fraturas, sobretudo com o envelhecimento.\nIndivíduos com IMC < 18 kg/m2 têm menor risco de ocorrência de osteoporose"},{"l":"C","t":"Indivíduos com IMC < 18 kg/m2 têm menor risco de ocorrência de osteoporose","e":"Falsa. Baixo IMC é fator de risco para osteoporose. Indivíduos muito magros tendem a ter menor reserva óssea e maior risco de fraturas.\nO uso de corticóides como por exemplo prednisona 20mg ao dia, por mais de 3 meses, não é fator para ocorrência de osteoporose, pois a dose da medicação utilizada é baixa"},{"l":"D","t":"O uso de corticóides como por exemplo prednisona 20mg ao dia, por mais de 3 meses, não é fator para ocorrência de osteoporose, pois a dose da medicação utilizada é baixa","e":"Falsa. Uso crônico de glicocorticoides, como prednisona por ≥3 meses, é fator importante de risco para osteoporose. 20 mg/dia é uma dose relevante, não baixa.\nEm uma paciente com 65 anos e T score <= -2,5, em coluna, fêmur total ou colo de fêmur, temos diagnóstico de osteoporose"},{"l":"E","t":"Em uma paciente com 65 anos e T score <= -2,5, em coluna, fêmur total ou colo de fêmur, temos diagnóstico de osteoporose","e":"Verdadeira. Em mulher de 65 anos, T-score ≤ -2,5 em coluna lombar, colo do fêmur ou fêmur total é compatível com osteoporose densitométrica."}],"type":"true_false"},{"n":26,"topic":"Metabolismo ósseo e paratireoide","difficulty":"médio","statement":"Bloco 9 — Metabolismo ósseo e paratireoide. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:V","B:F","C:V","D:V","E:V"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"O hiperparatireoidismo primário é causado por produção excessiva e secreção de paratormônio (PTH) por uma ou mais glândulas paratireoides.","e":"Verdadeira. O hiperparatireoidismo primário ocorre por secreção autônoma excessiva de PTH por uma ou mais paratireoides, geralmente por adenoma.\nO hiperparatireoidismo primário é uma causa comum de hipocalcemia"},{"l":"B","t":"O hiperparatireoidismo primário é uma causa comum de hipocalcemia","e":"Falsa. O hiperparatireoidismo primário costuma causar hipercalcemia, não hipocalcemia, pois o PTH aumenta o cálcio sérico.\nAs alterações mentais ou de comportamento podem fazer parte do quadro clínico do hiperparatireoidismo"},{"l":"C","t":"As alterações mentais ou de comportamento podem fazer parte do quadro clínico do hiperparatireoidismo","e":"Verdadeira. Alterações neuropsiquiátricas podem ocorrer, como fadiga, depressão, dificuldade de concentração e alterações de comportamento.\nA inadequação dos níveis de vitamina D é tida como uma das possíveis causas para falha do tratamento medicamentoso da osteoporose"},{"l":"D","t":"A inadequação dos níveis de vitamina D é tida como uma das possíveis causas para falha do tratamento medicamentoso da osteoporose","e":"Verdadeira. Deficiência ou insuficiência de vitamina D pode comprometer a resposta ao tratamento da osteoporose e deve ser corrigida.\nA vitamina D, produzida na pele ou ingerida, sofre transformações químicas até se transformar em sua forma ativa (calcitriol) com importantes funções na fisiologia ósteo-mineral"},{"l":"E","t":"A vitamina D, produzida na pele ou ingerida, sofre transformações químicas até se transformar em sua forma ativa (calcitriol) com importantes funções na fisiologia ósteo-mineral","e":"Verdadeira. A vitamina D passa por ativações até formar calcitriol, sua forma ativa, que participa principalmente da absorção intestinal de cálcio e fósforo."}],"type":"true_false"},{"n":27,"topic":"Metabolismo ósseo e paratireoide","difficulty":"médio","statement":"Bloco 10 — Metabolismo ósseo e paratireoide. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:F","B:F","C:F","D:F","E:F"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"Bifosfonatos são um grupo de drogas com boa absorção oral.","e":"Falsa. Os bisfosfonatos têm baixa absorção oral. Por isso, devem ser tomados em jejum, apenas com água, evitando alimentos e outros medicamentos logo após.\nA calcitonina é um análogo de hidroxiapatita"},{"l":"B","t":"A calcitonina é um análogo de hidroxiapatita","e":"Falsa. A calcitonina é um hormônio produzido pelas células C da tireoide e atua inibindo osteoclastos. Não é análogo de hidroxiapatita.\nA vitamina D deve ser ingerida com o estômago vazio para melhorar a biodisponibilidade."},{"l":"C","t":"A vitamina D deve ser ingerida com o estômago vazio para melhorar a biodisponibilidade.","e":"Falsa. A vitamina D é lipossolúvel e sua absorção tende a ser melhor quando ingerida com uma refeição que contenha gordura, não em jejum.\nA densitometria óssea de rotina na osteoporose primária tem maior valor diagnóstico se associada à dosagem de cálcio e fosfatase alcalina"},{"l":"D","t":"A densitometria óssea de rotina na osteoporose primária tem maior valor diagnóstico se associada à dosagem de cálcio e fosfatase alcalina","e":"Falsa. A densitometria óssea (DXA) tem valor diagnóstico por si só. Cálcio e fosfatase alcalina ajudam na investigação de causas secundárias, mas não aumentam diretamente o valor diagnóstico da DXA para osteoporose primária.\nAtividade física deve ser evitada em indivíduos com osteoporose comprovada"},{"l":"E","t":"Atividade física deve ser evitada em indivíduos com osteoporose comprovada","e":"Falsa. Atividade física não deve ser evitada. Exercícios com carga, resistência muscular e treino de equilíbrio ajudam a preservar massa óssea e reduzir risco de quedas."}],"type":"true_false"},{"n":28,"topic":"Hipófise — Hipofunção","difficulty":"médio","statement":"Bloco 11 — Hipófise — Hipofunção. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:V","B:V","C:F","D:F","E:V"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"A extensão supra-selar do tumor habitualmente leva a comprometimento ótico que torna necessária a realização de campimetria nestes casos.","e":"Verdadeira. Extensão suprasselar pode comprimir o quiasma óptico, causando alteração de campo visual; por isso, a campimetria está indicada."},{"l":"B","t":"Os sintomas podem ser inespecíficos e a doença subdiagnosticada, o que associa à redução da expectativa de vida.","e":"Verdadeira. A acromegalia pode evoluir de forma insidiosa, com sintomas inespecíficos, levando a diagnóstico tardio e aumento de morbimortalidade."},{"l":"C","t":"Depois que o diagnóstico laboratorial tiver sido estabelecido, deve-se realizar Tomografia Computadorizada (TC) de crânio, tórax e abdome para localização do tumor.","e":"Falsa. Após confirmação bioquímica, o exame de imagem de escolha é a RNM de sela túrcica/hipófise, e não TC de crânio, tórax e abdome de rotina."},{"l":"D","t":"O crescimento linear exagerado e gigantismo é muito comum e acontece quando a doença ocorre após o fechamento das cartilagens de crescimento.","e":"Falsa. Gigantismo ocorre quando o excesso de GH aparece antes do fechamento das cartilagens de crescimento. Após o fechamento, ocorre acromegalia, sem aumento importante da altura."},{"l":"E","t":"Ao diagnóstico, a maioria dos casos decorrem de macroadenomas hipofisários.","e":"Verdadeira. Muitos pacientes são diagnosticados tardiamente e já apresentam macroadenoma hipofisário."}],"type":"true_false"},{"n":29,"topic":"Hipófise — Hiperfunção","difficulty":"médio","statement":"Bloco 12 — Hipófise — Hiperfunção. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:V","B:F","C:V","D:F","E:V"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"As formas de alto peso molecular da prolactina (Macroprolactina) têm baixa bioatividade e são encontradas em baixos níveis na circulação.","e":"Verdadeira. A macroprolactina é uma forma de alto peso molecular, com baixa atividade biológica. Pode elevar a prolactina laboratorialmente com poucos ou nenhum sintoma."},{"l":"B","t":"Deve-se avaliar se há presença de sintomas e sinais relacionados à hiperprolactinemia, como aumento de libido.","e":"Falsa. A hiperprolactinemia costuma causar redução da libido, não aumento, além de hipogonadismo, galactorreia e infertilidade."},{"l":"C","t":"O achado de imagem sugestiva de adenoma hipofisário pode ser encontrado em até 10% da população normal e a ressonância magnética, sem sinais de patologia.","e":"Verdadeira. Pequenos incidentalomas hipofisários podem ser encontrados em indivíduos assintomáticos. Portanto, um nódulo de 0,5 cm pode ser incidental e não necessariamente explicar a PRL elevada."},{"l":"D","t":"A conduta é iniciar um teste terapêutico por 3 meses com um agonista dopaminérgico em dose baixa.","e":"Falsa. Não se deve iniciar agonista dopaminérgico apenas como “teste terapêutico”. Primeiro é preciso esclarecer a causa da hiperprolactinemia."},{"l":"E","t":"Deve-se pesquisar macroprolactinemia.","e":"Verdadeira. Como a prolactina está apenas moderadamente elevada e há um pequeno adenoma, deve-se pesquisar macroprolactinemia para evitar atribuir erroneamente a elevação ao microadenoma."}],"type":"true_false"},{"n":30,"topic":"Suprarrenal","difficulty":"médio","statement":"Bloco 13 — Suprarrenal. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:V","B:F","C:F","D:F","E:F"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"Este sintoma provavelmente resulta de síndrome de Sheehan.","e":"Verdadeira. A ausência de lactação no pós-parto pode ser manifestação precoce da síndrome de Sheehan, por deficiência de prolactina secundária à necrose hipofisária."},{"l":"B","t":"Este é um sinal precoce da síndrome de Cushing.","e":"Falsa. Falha na lactação não é manifestação típica de síndrome de Cushing."},{"l":"C","t":"Este sintoma sugere ter ocorrido uma complicação hemorrágica no parto.","e":"Falsa. A ausência de lactação isoladamente sugere deficiência de prolactina/hipopituitarismo, mas não permite concluir que houve uma complicação hemorrágica no parto. Para pensar em síndrome de Sheehan, precisa haver contexto obstétrico compatível, especialmente hemorragia pós-parto importante, hipotensão ou choque."},{"l":"D","t":"Este sintoma levanta a suspeita da síndrome de secreção inapropriada de ADH.","e":"Falsa. SIADH causa retenção de água e hiponatremia; não é causa típica de falha na lactação."},{"l":"E","t":"Este sintoma é comum em parturientes nesta faixa etária e não leva a suspeita de deficiência hormonal.","e":"Falsa. Ausência de lactação não deve ser considerada normal apenas pela idade da paciente; pode indicar deficiência de prolactina e hipopituitarismo."}],"type":"true_false"},{"n":31,"topic":"Hipófise — Hiperfunção","difficulty":"médio","statement":"Bloco 14 — Hipófise — Hiperfunção. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:F","B:F","C:F","D:F","E:F"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"Em relação à glicemia, o GH é um hormônio antagonista à insulina.","e":"Falsa. Do ponto de vista fisiológico moderno, o GH tem efeitos anti-insulínicos importantes, porque reduz a captação periférica de glicose e aumenta a produção hepática de glicose; porém, seus efeitos metabólicos são bifásicos: inicialmente pode ter efeitos semelhantes aos da insulina e, depois, predominam efeitos anti-insulínicos. Apesar de predominar efeito anti-insulínico em determinadas condições, a afirmação é excessivamente absoluta."},{"l":"B","t":"Em relação à glicemia, o GH é um hormônio antagonista ao glucagon.","e":"Falsa."},{"l":"C","t":"GH é um hormônio que não tem nenhuma relação com o metabolismo glicídico.","e":"Falsa. O GH não é antagonista do glucagon. Na verdade, ambos podem contribuir para aumentar a glicemia. O GH participa diretamente do metabolismo glicídico, tendo efeito hiperglicemiante e anti-insulínico."},{"l":"D","t":"GH é um hormônio cuja deficiência pode até ser causa de episódios hiperglicêmicos matinais em crianças.","e":"Falsa. A deficiência de GH tende a causar hipoglicemia, principalmente em crianças, e não hiperglicemia."},{"l":"E","t":"Durante a investigação de baixa estatura, para avaliar o nível de GH, o melhor marcador sérico é GH sérico matinal, porque sua secreção é pulsátil.","e":"Falsa. Como a secreção de GH é pulsátil, uma dosagem isolada de GH matinal não é confiável. Na investigação de deficiência de GH, utiliza-se IGF-1 e, quando necessário, testes de estímulo."}],"type":"true_false"},{"n":32,"topic":"Hipófise — Hiperfunção","difficulty":"médio","statement":"Bloco 15 — Hipófise — Hiperfunção. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:F","B:F","C:F","D:V","E:V"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"O lobo anterior corresponde a cerca de 20% da hipófise.","e":"Falsa. O lobo anterior (adeno-hipófise) corresponde à maior parte da hipófise, cerca de 75–80%, e não 20%."},{"l":"B","t":"A PRL não está sujeita à inibição por retroalimentação pelos hormônios produzidos em tecido-alvo.","e":"Falsa. Ela pode ser considerada falsa porque a prolactina possui feedback negativo, só que diferente dos outros eixos: a própria PRL estimula neurônios dopaminérgicos no hipotálamo, aumentando dopamina, e a dopamina então inibe os lactotrofos e reduz a secreção de PRL. Isso é chamado de feedback curto (short-loop feedback)."},{"l":"C","t":"O adenoma hipofisário mais frequente é o somatotropinoma (tumor secretor de hormônio de crescimento).","e":"Falsa. O adenoma hipofisário funcionante mais frequente é o prolactinoma, não o somatotropinoma."},{"l":"D","t":"A cirurgia é o tratamento de primeira escolha para todos os tumores hipofisários, com exceção dos prolactinomas.","e":"Verdadeira. Em muitos adenomas hipofisários funcionantes e não funcionantes, a cirurgia é o tratamento de escolha quando há indicação. A grande exceção clássica é o prolactinoma, cujo tratamento inicial costuma ser com agonista dopaminérgico, como cabergolina."},{"l":"E","t":"A secreção hipofisária pode ser influenciada também pelo ciclo diário claro-escuro","e":"Verdadeira. A secreção hipofisária sofre influência do ritmo circadiano. Exemplo: GH aumenta durante o sono e ACTH/cortisol apresentam variação ao longo do dia."}],"type":"true_false"},{"n":33,"topic":"Metabolismo ósseo e paratireoide","difficulty":"médio","statement":"Bloco 16 — Metabolismo ósseo e paratireoide. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:V","B:F","C:V","D:V","E:F"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"O tratamento do hiperparatireoidismo em geral é cirúrgico","e":"Verdadeira. O tratamento definitivo do hiperparatireoidismo primário sintomático é, em geral, cirúrgico, com paratireoidectomia."},{"l":"B","t":"Nunca há mais de uma glândula paratireóide afetada no hiperparatireoidismo","e":"Falsa. Pode haver acometimento de mais de uma paratireoide, especialmente nos casos de hiperplasia multiglandular."},{"l":"C","t":"As alterações mentais ou de comportamento podem fazer parte do quadro сlínico do hiperparatireoidismo","e":"Verdadeira. Alterações neuropsiquiátricas, como fadiga, depressão, dificuldade de concentração e alterações de comportamento, podem ocorrer no hiperparatireoidismo."},{"l":"D","t":"Não se deve retirar o cálcio da dieta do paciente com hiperparatireoidismo","e":"Verdadeira. Não se recomenda retirar cálcio da dieta. Deve-se manter ingestão adequada de cálcio, evitando restrição excessiva."},{"l":"E","t":"O tratamento do hipoparatireoidismo é feito com reposição de PTH","e":"Falsa. O tratamento convencional do hipoparatireoidismo é feito com cálcio + vitamina D ativa (calcitriol). Reposição de PTH fica reservada para casos selecionados."}],"type":"true_false"},{"n":34,"topic":"Metabolismo ósseo e paratireoide","difficulty":"médio","statement":"Paciente feminina de 63 anos, com antecedente de embolia pulmonar, diabetes e hipertensão, apresentou fratura de colo de fêmur há 6 meses, sendo diagnosticada com osteoporose de coluna (T escore -4,8) e do fêmur (T escore -2,9). Em uso atual de glibenclamida, metformina e enalapril. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:V","B:F","C:V","D:F","E:V"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"A osteoporose é uma doença silenciosa que afeta especialmente as mulheres na pós-menopausa e idosos e tem elevada taxa de morbimortalidade. O principal objetivo do tratamento da osteoporose é a prevenção das fraturas.","e":"Verdadeira. A osteoporose é muitas vezes silenciosa até ocorrer fratura, acomete principalmente mulheres pós-menopausa e idosos, e o objetivo central do tratamento é reduzir o risco de fraturas."},{"l":"B","t":"O exame mais adequado para o diagnóstico da osteoporose é a densitometria óssea, que permite avaliar o grau da doença e serve como método de acompanhamento do tratamento. O valor < -1,5 DP (desvio padrão) no exame de densitometria faz o diagnóstico de osteoporose.","e":"Falsa. A densitometria óssea é o exame de referência, mas o diagnóstico densitométrico de osteoporose em mulheres pós-menopausa é feito com T-score ≤ -2,5, e não < -1,5.\n≥ -1,0: normal\nentre -1,0 e -2,5: osteopenia\n≤ -2,5: osteoporose"},{"l":"C","t":"O cálcio é um nutriente importante na prevenção da osteoporose. A ingestão inadequada pode resultar em redução da massa óssea. Além assim, é importante uma adequada oferta de cálcio proveniente da alimentação.","e":"Verdadeira. O cálcio é importante para manutenção da massa óssea, e ingestão inadequada pode contribuir para perda óssea."},{"l":"D","t":"Alguns fatores de risco importantes relacionados à osteoporose e a fraturas na pós-menopausa são: idade, sexo masculino, etnia branca ou oriental, história prévia pessoal e familiar de fratura, obesidade, tabagismo, ingestão abusiva de bebidas alcoólicas e atividade física aeróbica.","e":"Falsa. A alternativa mistura fatores de risco verdadeiros com falsos. São fatores de risco: idade avançada, baixo peso, tabagismo, álcool excessivo, história de fratura e sedentarismo. Já sexo masculino, obesidade e atividade física aeróbica não são fatores de risco clássicos dessa forma."},{"l":"E","t":"Os bisfosfonatos são a classe de drogas considerada de primeira linha para o tratamento da osteoporose na pós-menopausa e agem inibindo a atividade dos osteoclastos.","e":"Verdadeira. Os bisfosfonatos são anti-reabsortivos e atuam principalmente inibindo a atividade dos osteoclastos, sendo tratamento de primeira linha em muitos pacientes com osteoporose pós-menopausa."}],"type":"true_false"},{"n":35,"topic":"Metabolismo ósseo e paratireoide","difficulty":"médio","statement":"Bloco 18 — Metabolismo ósseo e paratireoide. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:F","B:V","C:V","D:V","E:F"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"Os osteoclastos são células responsáveis pela formação óssea.","e":"Falsa. Os osteoclastos fazem reabsorção óssea, ou seja, degradam o osso. Quem forma osso são os osteoblastos."},{"l":"B","t":"O metabolismo ósseo é acoplado, ou seja, ocorre formação nos locais onde houve reabsorção prévia.","e":"Verdadeira. O remodelamento ósseo é acoplado: primeiro ocorre reabsorção por osteoclastos e depois formação óssea por osteoblastos no mesmo local."},{"l":"C","t":"O PTH (paratormônio) atua no aumento da calcemia, sendo que a secreção do PTH promove a desmineralização óssea, aumentando os níveis de Ca no sangue.","e":"Verdadeira. O PTH aumenta a calcemia. Entre seus efeitos, favorece reabsorção óssea, aumenta reabsorção renal de cálcio e estimula a formação de calcitriol."},{"l":"D","t":"Os osteoblastos são responsáveis pela síntese de matriz óssea.","e":"Verdadeira. Os osteoblastos sintetizam a matriz óssea, principalmente o osteóide, participando da formação do osso."},{"l":"E","t":"O osteócito é o estágio final de diferenciação do osteoclasto.","e":"Falsa. O osteócito é o estágio final de diferenciação do osteoblasto, não do osteoclasto."}],"type":"true_false"},{"n":36,"topic":"Suprarrenal","difficulty":"médio","statement":"Bloco 19 — Suprarrenal. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:V","B:V","C:V","D:F","E:V"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"A síndrome de Cushing dependente da hipófise, conhecida como Doença de Cushing, é a causa mais comum de síndrome de Cushing endógena.","e":"Verdadeira. A doença de Cushing é causada por adenoma hipofisário secretor de ACTH e é a causa mais comum de síndrome de Cushing endógena."},{"l":"B","t":"O uso de glicocorticóides como medicação é a causa mais frequente da síndrome de Cushing.","e":"Verdadeira. O uso crônico de glicocorticoides exógenos é a causa mais frequente de síndrome de Cushing no geral."},{"l":"C","t":"O teste de supressão com dexametasona é um bom teste para investigar síndrome de Cushing.","e":"Verdadeira. O teste de supressão com dexametasona é um dos testes usados para rastrear hipercortisolismo. Na síndrome de Cushing, o cortisol não suprime adequadamente."},{"l":"D","t":"No hiperaldosteronismo primário, o paciente apresenta cefaléia holocraniana, hipertensão arterial em picos, hipercalemia e sudorese.","e":"Falsa. Esse quadro lembra mais feocromocitoma. No hiperaldosteronismo primário, o típico é HAS + renina baixa + aldosterona alta, podendo haver hipocalemia, e não hipercalemia."},{"l":"E","t":"As metanefrinas plasmáticas são o exame de escolha inicial para investigação no diagnóstico de feocromocitoma.","e":"Verdadeira. As metanefrinas plasmáticas livres são um dos principais exames iniciais para investigação de feocromocitoma; metanefrinas urinárias fracionadas também podem ser utilizadas."}],"type":"true_false"},{"n":37,"topic":"Suprarrenal","difficulty":"médio","statement":"Bloco 20 — Suprarrenal. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:V","B:V","C:V","D:V","E:F"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"Em um paciente hipertenso com suspeita de feocromocitoma, um teste bioquímico para confirmar essa hipótese seria a dosagem de metanefrinas (plasmáticas ou urinárias).","e":"Verdadeira. Na suspeita de feocromocitoma, a investigação bioquímica é feita com metanefrinas plasmáticas livres ou metanefrinas urinárias fracionadas."},{"l":"B","t":"A sintomatologia dos feocromocitomas pode se apresentar como: hipertensão, palpitações, sudorese e cefaleia.","e":"Verdadeira. O feocromocitoma pode cursar com HAS, palpitações, sudorese e cefaleia. A tríade clássica é cefaleia + sudorese + palpitações."},{"l":"C","t":"Uma mulher de 38 anos com hipocalemia persistente, expansão crônica do volume plasmático e hipertensão arterial sistêmica tem possibilidade de um diagnóstico de hiperaldosteronismo primário.","e":"Verdadeira. O hiperaldosteronismo primário causa retenção de sódio e água, expansão volêmica e HAS, além de aumentar a excreção renal de potássio, podendo causar hipocalemia."},{"l":"D","t":"Hiperaldosteronismo primário e feocromocitoma são causas de hipertensão arterial secundária.","e":"Verdadeira. Tanto o hiperaldosteronismo primário quanto o feocromocitoma são causas endócrinas clássicas de hipertensão arterial secundária."},{"l":"E","t":"Em pacientes com suspeita clínica de síndrome de Cushing, o primeiro passo é a detecção da lesão causadora por meio de exames de imagem (tomografia de tórax inicialmente e, em seguida, de crânio).","e":"Falsa. Na suspeita de síndrome de Cushing, o primeiro passo é confirmar bioquimicamente o hipercortisolismo, e não procurar a lesão por imagem. Só depois se investiga a etiologia."}],"type":"true_false"},{"n":38,"topic":"Suprarrenal","difficulty":"médio","statement":"Bloco 21 — Suprarrenal. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:F","B:V","C:V","D:V","E:F"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"Durante a investigação laboratorial, já tendo sido confirmado o hipercortisolismo, se encontrarmos uma dosagem de ACTH alta na síndrome de Cushing, esse fato aponta para uma provável patologia primária da suprarrenal.","e":"Falsa. ACTH alto indica síndrome de Cushing ACTH-dependente, sugerindo origem hipofisária ou ectópica. Na causa adrenal, o cortisol é produzido autonomamente e o ACTH fica baixo/suprimido."},{"l":"B","t":"Os feocromocitomas são tumores secretores de catecolaminas que apesar de raros implicam em elevada morbimortalidade (efeitos metabólicos e cardiovasculares).","e":"Verdadeira. Feocromocitomas secretam catecolaminas e podem causar crises hipertensivas, arritmias e outras complicações cardiovasculares importantes."},{"l":"C","t":"Uma lesão em adrenal > 6 cm, margens irregulares e áreas de necrose é sugestiva de malignidade.","e":"Verdadeira. Lesão adrenal grande, irregular, heterogênea e com necrose levanta suspeita de malignidade. O corte de >6 cm é clássico em provas mais antigas."},{"l":"D","t":"Os adenomas produtores de aldosterona têm como manifestação mais característica a hipertensão arterial sistêmica associada à hipocalemia, no entanto nós podemos ter hiperaldosteronismo primário normocalêmico.","e":"Verdadeira. Hiperaldosteronismo primário costuma causar HAS ± hipocalemia. Muitos pacientes, porém, apresentam potássio normal."},{"l":"E","t":"Os feocromocitomas são na maioria das vezes bilaterais e malignos.","e":"Falsa. A maioria dos feocromocitomas é unilateral e não apresenta comportamento metastático. Bilateralidade é mais associada a formas hereditárias."}],"type":"true_false"},{"n":39,"topic":"Hipófise — Hipofunção","difficulty":"médio","statement":"Bloco 22 — Hipófise — Hipofunção. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:F","B:V","C:V","D:F","E:V"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"Temos panhipopituitarismo quando ocorre a redução de dois ou mais hormônios hipofisários decorrente de condições que acometem a região hipotálamo-hipofisária.","e":"Falsa. Pan-hipopituitarismo significa deficiência de praticamente todos os hormônios da adeno-hipófise, e não apenas de dois ou mais. Deficiência de dois ou mais eixos é hipopituitarismo múltiplo."},{"l":"B","t":"Entre as causas de hipopituitarismo podemos ter razões congênitas ou adquiridas.","e":"Verdadeira. O hipopituitarismo pode ter causas congênitas (genéticas/desenvolvimento) ou adquiridas."},{"l":"C","t":"São exemplos de causas adquiridas do hipopituitarismo: tumor hipofisário, traumatismo crônico encefálico, doenças inflamatórias e infiltrativas, necrose hipofisária pós-parto (síndrome de Sheehan).","e":"Verdadeira. Tumores, traumatismo craniano, doenças inflamatórias/infiltrativas e síndrome de Sheehan são causas adquiridas clássicas."},{"l":"D","t":"Podemos ter sintomas decorrentes de uma compressão (efeito de massa) por uma lesão como: cefaleia, alterações de campo visual, paralisias de nervos periféricos.","e":"Falsa. Lesões expansivas podem causar cefaleia, alterações do campo visual e paralisias de nervos cranianos por compressão de estruturas vizinhas."},{"l":"E","t":"Muitas vezes o diagnóstico é tardio devido às manifestações clínicas inespecíficas. O quadro clínico varia conforme o tipo de deficiência hormonal, a velocidade de instalação, o sexo, a idade e a causa do hipopituitarismo.","e":"Verdadeira. O quadro pode ser insidioso e variar conforme qual eixo hormonal falhou, intensidade, velocidade de instalação, idade e etiologia."}],"type":"true_false"},{"n":40,"topic":"Hipófise — Hiperfunção","difficulty":"médio","statement":"Bloco 23 — Hipófise — Hiperfunção. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:V","B:V"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"A deficiência de GH nas crianças ocasiona uma baixa estatura e retardo do crescimento.","e":"Verdadeira. A deficiência de GH na infância reduz o crescimento linear, levando a baixa estatura e redução da velocidade de crescimento."},{"l":"B","t":"A deficiência de TSH devido ao hipopituitarismo tem manifestações clínicas semelhantes ao hipotireoidismo primário, podendo ser o hipotireoidismo de origem central mais insidioso e com clínica mais leve.","e":"Verdadeira. A deficiência de TSH causa hipotireoidismo central, com manifestações semelhantes ao hipotireoidismo primário, como fadiga, sonolência, constipação e intolerância ao frio. Em geral, pode ter apresentação mais insidiosa.\na"}],"type":"true_false"},{"n":41,"topic":"Suprarrenal","difficulty":"médio","statement":"Bloco 24 — Suprarrenal. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:V","B:F","C:F","D:F","E:F"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"A osteoporose é definida por baixa massa óssea associada à deterioração da microarquitetura do osso com aumento do risco de fragilidade e de fraturas.","e":"Verdadeira. A osteoporose cursa com baixa massa óssea e deterioração da microarquitetura, aumentando a fragilidade e o risco de fraturas."},{"l":"B","t":"Doença de Cushing e hipogonadismo são causas muito comuns de osteoporose, por isso devemos investigar todos os pacientes para essas doenças.","e":"Falsa. Síndrome de Cushing e hipogonadismo podem causar osteoporose secundária, mas não devem ser investigados indiscriminadamente em todos os pacientes; a pesquisa depende da história clínica e dos fatores de risco."},{"l":"C","t":"O baixo peso IMC < 18 kg/m² é um fator de risco em relação à ocorrência de osteoporose. Já o uso de corticoides é um fator protetor pela sua ação anti-inflamatória.","e":"Falsa. Baixo peso é fator de risco, mas o uso crônico de glicocorticoides também aumenta o risco de osteoporose; não é fator protetor."},{"l":"D","t":"O tratamento da osteoporose com bisfosfonatos pode ser mantido continuamente por mais de dez anos sem riscos para o paciente.","e":"Falsa. Bisfosfonatos não devem ser mantidos indefinidamente sem reavaliação. Uso prolongado pode aumentar risco de eventos como fratura atípica de fêmur e osteonecrose de mandíbula."},{"l":"E","t":"Os bisfosfonatos são medicações anabólicas e estimuladoras da reabsorção óssea.","e":"Falsa. Bisfosfonatos são anti-reabsortivos: inibem a atividade dos osteoclastos. Não são anabólicos nem estimulam reabsorção óssea."}],"type":"true_false"},{"n":42,"topic":"Hipófise — Hiperfunção","difficulty":"médio","statement":"Bloco 25 — Hipófise — Hiperfunção. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:V","B:V","C:F","D:F","E:F"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"Na avaliação das pacientes com hiperprolactinemia é importante questionar se a paciente tem sintomas relacionados (amenorreia/irregularidade menstrual, galactorreia).","e":"Verdadeira. Amenorreia, irregularidade menstrual e galactorreia são manifestações clássicas da hiperprolactinemia e devem ser pesquisadas."},{"l":"B","t":"A hiperprolactinemia patológica pode ser causada por insuficiência renal e hepática, hipotireoidismo, desconexão de haste hipofisária e prolactinoma.","e":"Verdadeira. Insuficiência renal/hepática, hipotireoidismo, efeito de haste e prolactinoma são causas reconhecidas de hiperprolactinemia."},{"l":"C","t":"Diante desse achado de hiperprolactinemia, o passo seguinte é solicitar ressonância nuclear de sela túrcica para investigação de possível adenoma hipofisário, causa mais comum de hiperprolactinemia.","e":"Falsa. A RNM não é necessariamente o passo seguinte imediato. Antes, deve-se excluir causas secundárias e considerar macroprolactinemia, especialmente com elevação moderada de PRL."},{"l":"D","t":"O aumento da macroprolactina é a responsável por mais de 90% dos casos de hiperprolactinemia em homens.","e":"Falsa. Macroprolactina pode causar hiperprolactinemia assintomática, mas não responde por >90% dos casos em homens."},{"l":"E","t":"A magnitude da elevação nos níveis séricos de prolactina é útil na determinação da etiologia, uma vez que os valores mais altos são encontrados em pacientes com hiperprolactinemia farmacológica.","e":"Falsa. A magnitude da PRL ajuda na etiologia, mas os valores mais altos costumam ocorrer nos prolactinomas, sobretudo macroprolactinomas, e não na forma farmacológica."}],"type":"true_false"},{"n":43,"topic":"Hipófise — Hiperfunção","difficulty":"médio","statement":"Bloco 26 — Hipófise — Hiperfunção. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:F","B:V","C:V","D:F","E:F"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"As complicações respiratórias são as primeiras causas de mortalidade nos pacientes com acromegalia.","e":"Falsa. As principais causas de mortalidade na acromegalia são sobretudo cardiovasculares, não respiratórias."},{"l":"B","t":"Nos pacientes em que o diagnóstico não puder ser descartado ou confirmado com as dosagens basais de GH e IGF-1, está indicada a dosagem do GH durante teste oral de tolerância à glicose.","e":"Verdadeira. Quando GH e IGF-1 basais não esclarecem o diagnóstico, realiza-se TOTG com dosagem de GH. Na acromegalia, o GH não suprime adequadamente após a glicose."},{"l":"C","t":"A cirurgia é considerada a terapia de primeira escolha no tratamento da acromegalia e, na maioria dos casos, realizada por via transesfenoidal.","e":"Verdadeira. A cirurgia transesfenoidal é o tratamento de primeira escolha na maioria dos adenomas hipofisários ressecáveis."},{"l":"D","t":"O principal mecanismo envolvido na gênese dos sintomas da acromegalia é a hipersecreção de GHRH (growth-hormone-releasing hormone – GHRH) hipotalâmico.","e":"Falsa. A causa habitual é adenoma hipofisário secretor de GH, com aumento secundário de IGF-1. Hipersecreção de GHRH é rara."},{"l":"E","t":"Na maioria das vezes, a ressonância nuclear magnética (RNM) de sela túrcica evidencia um microadenoma hipofisário.","e":"Falsa. Na maioria dos casos, o diagnóstico é tardio e a RNM mostra macroadenoma, não microadenoma."}],"type":"true_false"},{"n":44,"topic":"Metabolismo ósseo e paratireoide","difficulty":"médio","statement":"Analise o caso clínico e responda a questão a seguir: Mulher, 70 anos, pós-menopausa há 22 anos, comparece para avaliação por dor dorsal e antecedente de fratura vertebral detectada em radiografia. Nega trauma importante. Refere baixo peso, sedentarismo e etilismo crônico. Densitometria óssea: Coluna lombar: T-score = -2,4 Colo do fêmur: T-score = -2,6. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:V","B:V","C:V","D:F","E:F"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"A presença de fratura vertebral por fragilidade é um marcador importante de fragilidade óssea e risco de novas fraturas.","e":"Verdadeira. Fratura vertebral por baixo impacto é marcador de fragilidade óssea e aumenta bastante o risco de novas fraturas."},{"l":"B","t":"O etilismo crônico pode contribuir para redução de massa óssea e aumento do risco de fraturas.","e":"Verdadeira. O etilismo crônico favorece perda de massa óssea, piora a qualidade óssea e aumenta o risco de quedas e fraturas."},{"l":"C","t":"Nesta paciente, há critério densitométrico para osteoporose.","e":"Verdadeira. Há critério densitométrico para osteoporose porque o T-score do colo do fêmur é -2,6, ou seja, ≤ -2,5."},{"l":"D","t":"O T-score deve ser substituído obrigatoriamente pelo Z-score em mulheres idosas.","e":"Falsa. Em mulheres pós-menopausa e idosos, usa-se principalmente o T-score. O Z-score é mais útil em mulheres pré-menopausa, homens <50 anos e crianças."},{"l":"E","t":"O tratamento da osteoporose se baseia exclusivamente em medicações, sem relevância de medidas comportamentais.","e":"Falsa. O tratamento não é apenas medicamentoso. Medidas como atividade física, prevenção de quedas, cessação do tabagismo, redução do álcool e adequação de cálcio/vitamina D são importantes."}],"type":"true_false"},{"n":45,"topic":"Metabolismo ósseo e paratireoide","difficulty":"médio","statement":"Bloco 28 — Metabolismo ósseo e paratireoide. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:F","B:V","C:F","D:V","E:F"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"A principal alteração fisiopatológica da osteoporose induzida por glicocorticóides é o aumento persistente da formação óssea por hiperatividade osteoblástica compensatória.","e":"Falsa. Glicocorticoides reduzem a formação óssea, principalmente por inibir osteoblastos, além de favorecer reabsorção óssea e reduzir absorção intestinal de cálcio."},{"l":"B","t":"Hipogonadismo pode contribuir para perda de massa óssea em homens.","e":"Verdadeira. O hipogonadismo reduz o estímulo hormonal sobre o osso e pode causar perda de massa óssea e maior risco de fraturas em homens."},{"l":"C","t":"Homens não devem ser investigados para osteoporose, pois trata-se de doença exclusivamente feminina.","e":"Falsa. Osteoporose também ocorre em homens, principalmente com idade avançada, hipogonadismo, uso de corticoide ou fratura por fragilidade."},{"l":"D","t":"A avaliação clínica de fatores de risco e fraturas prévias é importante na estratificação de risco.","e":"Verdadeira. História de fraturas, uso de medicamentos e fatores de risco são fundamentais para avaliar o risco de novas fraturas e causas secundárias."},{"l":"E","t":"A presença de fratura por fragilidade em homem, especialmente em idosos, costuma ser um achado esperado do envelhecimento e dispensa investigação etiológica adicional na maioria dos casos.","e":"Falsa. Fratura por fragilidade em homem não deve ser considerada apenas “do envelhecimento”; exige investigação de osteoporose e de causas secundárias."}],"type":"true_false"},{"n":46,"topic":"Metabolismo ósseo e paratireoide","difficulty":"médio","statement":"Bloco 29 — Metabolismo ósseo e paratireoide. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:V","B:V","C:V","D:F","E:V"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"O Caso 1 é compatível com hiperparatireoidismo primário, enquanto o Caso 2 sugere hipoparatireoidismo pós-cirúrgico, sendo ambos os diagnósticos sustentados pela correlação entre quadro clínico e padrão laboratorial.","e":"Verdadeira.\nCaso 1: Ca ↑ + PTH ↑ + fósforo ↓ → hiperparatireoidismo primário.\nCaso 2: Ca ↓ + PTH ↓ + fósforo ↑ após tireoidectomia → hipoparatireoidismo pós-cirúrgico."},{"l":"B","t":"A hipofosfatemia no Caso 1 e a hiperfosfatemia no Caso 2 podem ser explicadas, respectivamente, pela presença e pela deficiência da ação do PTH sobre a excreção renal de fósforo.","e":"Verdadeira. O PTH aumenta a excreção renal de fósforo. Assim:\nPTH ↑ → fósforo ↓ → hipofosfatemia → hiperparatireoidismo primário.\nPTH ↓ → fósforo ↑ → hipoparatireoidismo pós-cirúrgico."},{"l":"C","t":"A presença de nefrolitíase no Caso 1 e de espasmo carpopedal no Caso 2 pode ser compreendida como manifestações clínicas relacionadas às alterações do metabolismo do cálcio.","e":"Verdadeira.\nNo Caso 1, hipercalcemia favorece nefrolitíase.\nNo Caso 2, hipocalcemia aumenta excitabilidade neuromuscular, causando cãibras e espasmo carpopedal."},{"l":"D","t":"No Caso 1, exames de localização, como ultrassonografia cervical e cintilografia com sestamibi, são indispensáveis para estabelecer o diagnóstico inicial da doença.","e":"Falsa. O diagnóstico do hiperparatireoidismo primário é bioquímico, com cálcio e PTH. USG cervical e sestamibi são exames de localização pré-operatória, não para confirmar o diagnóstico."},{"l":"E","t":"No Caso 2, a reposição de cálcio e calcitriol pode ser necessária, enquanto no Caso 1 a doença pode cursar com repercussões ósseas, incluindo redução de massa óssea e aumento do risco de fraturas.","e":"Verdadeira. No hipoparatireoidismo, pode ser necessária reposição de cálcio + calcitriol. Já o hiperparatireoidismo pode causar reabsorção óssea, osteopenia/osteoporose e maior risco de fraturas."}],"type":"true_false"},{"n":47,"topic":"Hipófise — Hiperfunção","difficulty":"médio","statement":"Bloco 30 — Hipófise — Hiperfunção. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:V","B:V","C:V","D:F","E:F"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"As complicações cardiovasculares são as primeiras causas de mortalidade nos pacientes com acromegalia.","e":"Verdadeira. As complicações cardiovasculares estão entre as principais causas de mortalidade na acromegalia, especialmente por HAS, cardiomiopatia e alterações metabólicas."},{"l":"B","t":"Nos pacientes em que o diagnóstico não pode ser descartado ou confirmado com as dosagens basais de GH e IGF-1, está indicada a dosagem do GH durante teste oral de tolerância à glicose.","e":"Verdadeira. Quando GH e IGF-1 basais não esclarecem o diagnóstico, pode-se realizar TOTG com dosagem de GH. Na acromegalia, o GH não suprime adequadamente após a glicose."},{"l":"C","t":"A cirurgia é considerada a terapia de primeira escolha no tratamento da acromegalia e na maioria dos casos realizada por via transesfenoidal.","e":"Verdadeira. A cirurgia transesfenoidal é o tratamento de primeira escolha na maioria dos pacientes com adenoma hipofisário ressecável."},{"l":"D","t":"Geralmente a ressonância nuclear magnética (RNM) de sela túrcica evidencia um microadenoma hipofisário.","e":"Falsa. Na maioria dos casos, o diagnóstico ocorre tardiamente e a RNM evidencia macroadenoma, não microadenoma."},{"l":"E","t":"O principal mecanismo envolvido na gênese dos sintomas da acromegalia é a hipersecreção de GHRH (growth-hormone releasing hormone GHRH) hipotalâmico.","e":"Falsa. A causa habitual é um adenoma hipofisário secretor de GH, levando a aumento de IGF-1. Hipersecreção de GHRH é causa rara de acromegalia."}],"type":"true_false"},{"n":48,"topic":"Hipófise — Hiperfunção","difficulty":"médio","statement":"Bloco 31 — Hipófise — Hiperfunção. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:F","B:V","C:F","D:V","E:F"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"A cirrose hepática causa hiperprolactinemia por provocar diminuição da depuração renal do hormônio.","e":"Falsa. A cirrose pode causar hiperprolactinemia por redução da depuração/metabolização da prolactina, mas a frase erra ao atribuir isso especificamente à depuração renal."},{"l":"B","t":"Ao se deparar com aumento nos níveis de prolactina na ausência de sintomas compatíveis com hiperprolactinemia, é preciso suspeitar da presença de macroprolactina.","e":"Verdadeira. Hiperprolactinemia com poucos ou nenhum sintoma deve levantar suspeita de macroprolactina, forma de alto peso molecular e baixa atividade biológica."},{"l":"C","t":"A produção ectópica de PRL por tumores extra-hipofisários é a causa patológica mais frequente de hiperprolactinemia.","e":"Falsa. Produção ectópica de prolactina é rara. Entre as causas patológicas hipofisárias, o prolactinoma é muito mais frequente."},{"l":"D","t":"O prolactinoma representa o adenoma funcionante hipofisário mais frequente.","e":"Verdadeira. O prolactinoma é o adenoma hipofisário funcionante mais comum."},{"l":"E","t":"O hipotireoidismo primário pode ser causa de hiperprolactinemia, a qual é provocada pela diminuição do hormônio liberador de tireotrofina (TRH).","e":"Falsa. No hipotireoidismo primário ocorre aumento de TRH, não diminuição. O TRH elevado pode estimular os lactotrofos e aumentar a prolactina."}],"type":"true_false"},{"n":49,"topic":"Suprarrenal","difficulty":"médio","statement":"Bloco 32 — Suprarrenal. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:F","B:V","C:F","D:V","E:V"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"No diagnóstico de feocromocitoma a dosagem das catecolaminas plasmáticas é o exame de maior sensibilidade diagnóstica. __________","e":"Falsa. No feocromocitoma, os exames bioquímicos mais sensíveis são as metanefrinas plasmáticas livres ou metanefrinas urinárias fracionadas, e não a dosagem direta de catecolaminas plasmáticas. → Correção: “No diagnóstico de feocromocitoma, a dosagem de metanefrinas plasmáticas ou urinárias apresenta maior sensibilidade diagnóstica.”"},{"l":"B","t":"No hipercortisolismo o ACTH estar alto ou normal-alto no Cushing hipofisário e baixo/suprimido no Cushing adrenal. __________","e":"Verdadeira. No Cushing hipofisário, o ACTH costuma estar elevado ou inadequadamente normal; no Cushing adrenal, o cortisol é produzido autonomamente e o ACTH fica baixo/suprimido."},{"l":"C","t":"A droga de primeira escolha no preparo pré-operatório do feocromocitoma é o betabloqueador. __________","e":"Falsa. O preparo pré-operatório começa com bloqueio alfa-adrenérgico, e não beta-bloqueio. Betabloqueador só deve ser usado depois do bloqueio alfa, se necessário para controlar taquicardia. → Correção: “A droga de primeira escolha no preparo pré-operatório do feocromocitoma é um alfa-bloqueador.”"},{"l":"D","t":"A tríade clássica de feocromocitoma é taquicardia, sudorese e cefaléia. __________","e":"Verdadeira. A tríade clássica do feocromocitoma é cefaleia + sudorese + palpitações/taquicardia, frequentemente associada a hipertensão."},{"l":"E","t":"Presença de giba, fácies em lua cheia, estrias violáceas e osteoporose são achados frequentes na síndrome de Cushing. __________","e":"Verdadeira. Giba dorsocervical, fácies em lua cheia, estrias violáceas e osteoporose são manifestações típicas do hipercortisolismo."}],"type":"true_false"},{"n":50,"topic":"Suprarrenal","difficulty":"médio","statement":"Bloco 33 — Suprarrenal. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:V","B:F","C:F","D:V","E:V"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"Alguns fatores transcripcionais causam hipopituitarismo congênito: Pit-1, PROP 1, e HESX1.","e":"Verdadeira. Mutações em fatores de transcrição como PIT-1, PROP-1 e HESX1 podem causar hipopituitarismo congênito, por comprometer o desenvolvimento e a função da hipófise."},{"l":"B","t":"As causas mais comuns de hipopituitarismo adquirido são tumorais e pós quimioterapia.","e":"Falsa. As causas adquiridas mais comuns incluem principalmente tumores hipofisários e seu tratamento com cirurgia ou radioterapia, e não quimioterapia como causa clássica principal."},{"l":"C","t":"A anemia falciforme, sarcoidose e hemocromatose apresentam a mesma etiopatogenia de hipofunção da hipófise.","e":"Falsa. Essas doenças podem afetar a hipófise, mas por mecanismos diferentes: sarcoidose e hemocromatose são infiltrativas, enquanto anemia falciforme pode causar lesão por eventos vasculares/isquêmicos."},{"l":"D","t":"Os achados laboratoriais podem incluir: ACTH baixo ou normal, TSH baixo ou discretamente elevado e Testosterona baixa.","e":"Verdadeira. No hipopituitarismo, os hormônios periféricos podem estar baixos com hormônios hipofisários baixos ou inadequadamente normais. Assim, pode haver ACTH baixo/normal, TSH baixo ou discretamente elevado e testosterona baixa."},{"l":"E","t":"O quadro clínico de insuficiência adrenal central apresenta: hipotensão postural, perda de peso, fraqueza e náuseas.","e":"Verdadeira. A insuficiência adrenal central pode causar fraqueza, náuseas, perda de peso e hipotensão, por deficiência de cortisol."}],"type":"true_false"},{"n":51,"topic":"Suprarrenal","difficulty":"médio","statement":"Bloco 34 — Suprarrenal. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:V","B:V","C:F","D:F","E:V"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"Os adenomas não funcionantes cursam com hiperprolactinemia devido compressão de haste hipofisária.","e":"Verdadeiro. Adenomas hipofisários não funcionantes podem causar hiperprolactinemia por efeito de haste: a compressão da haste reduz a chegada de dopamina à hipófise, retirando a inibição sobre a prolactina."},{"l":"B","t":"O déficit de GH no adulto pode cursar com indisposição e fraqueza.","e":"Verdadeiro. Déficit de GH no adulto pode cursar com fadiga, indisposição, fraqueza, redução de massa magra e piora da qualidade de vida."},{"l":"C","t":"No hipotireoidismo secundário, o seguimento laboratorial deve ser feito com dosagem de TSH e T4 Livre.","e":"Falsa. No hipotireoidismo central, o TSH não é confiável para seguimento. O acompanhamento deve ser feito principalmente pelo T4 livre, ajustando a levotiroxina para mantê-lo em faixa adequada."},{"l":"D","t":"A apoplexia hipofisária e os meningeomas possuem etiologia vascular no hipopituitarismo.","e":"Falsa. A apoplexia hipofisária tem etiologia vascular/hemorrágica, mas meningioma é uma lesão tumoral, não vascular."},{"l":"E","t":"O paciente com insuficiência adrenal central (secundária) cursa com déficit apenas dos glicocorticóides, com preservação do eixo mineralocorticoide.","e":"Verdadeiro. Na insuficiência adrenal central há deficiência de ACTH → cortisol baixo, mas a aldosterona costuma estar preservada porque é regulada principalmente pelo sistema renina-angiotensina-aldosterona."}],"type":"true_false"},{"n":52,"topic":"Suprarrenal","difficulty":"médio","statement":"Bloco 35 — Suprarrenal. Julgue cada assertiva como verdadeira ou falsa.","correct":["A:F","B:V","C:F","D:F","E:F"],"general":"Analise cada assertiva de forma independente, relacionando o padrão clínico e laboratorial à fisiologia e à conduta endocrinológica.","summary":"Bloco de verdadeiro ou falso revisado e consolidado a partir das listas da prova.","memory":"Julgue cada frase pelo mecanismo fisiológico e evite generalizações absolutas.","trap":"Todas as assertivas devem ser respondidas antes da submissão.","alts":[{"l":"A","t":"O cushing adrenal apresenta quadro clínico mais agressivo, com hipercortisolismo persistente mesmo após retirada do tumor adrenal.","e":"Falsa. No Cushing adrenal, a retirada do tumor produtor de cortisol tende a corrigir o hipercortisolismo. Pode haver insuficiência adrenal transitória no pós-operatório por supressão do eixo HHA."},{"l":"B","t":"Há inúmeros análogos sintéticos de cortisol, utilizados principalmente como anti-inflamatórios, antialérgicos e imunodepressores. Assim, o Cushing medicamentoso é a principal causa de hipercortisolismo na população.","e":"Verdadeira. O uso crônico de glicocorticoides exógenos é a causa mais comum de síndrome de Cushing na população."},{"l":"C","t":"Um efeito adverso induzido por corticoides é a osteoporose, perda de peso e hipotensão postural.","e":"Falsa. Corticoides podem causar osteoporose, mas costumam levar a ganho de peso e hipertensão, não perda de peso e hipotensão postural."},{"l":"D","t":"O teste de Liddle 2, supressão com dexametasona 8 mg é a melhor forma de confirmação de excesso de cortisol endógeno.","e":"Falsa. O teste com 8 mg de dexametasona (Liddle 2) não é usado para confirmar hipercortisolismo. Ele era utilizado na investigação etiológica, especialmente para diferenciar doença de Cushing de outras causas ACTH-dependentes. Para confirmar hipercortisolismo usam-se testes como dexametasona 1 mg, cortisol salivar noturno ou cortisol livre urinário."},{"l":"E","t":"O tratamento cirúrgico com retirada tumoral deve ser primeira opção terapêutica em todos os casos de síndrome de Cushing. Radioterapia e bloqueadores da esteroidogênese adrenal, fazem parte da segunda linha de tratamento.","e":"Falsa. Cirurgia não é primeira opção em todos os casos. Depende da etiologia. Por exemplo, no Cushing iatrogênico por corticoide não há tumor para operar."}],"type":"true_false"}]$data$::jsonb)
    AS x(n integer,topic text,difficulty text,statement text,type text,correct jsonb,general text,summary text,memory text,trap text,alts jsonb)
  LOOP
    SELECT id INTO t FROM public.topics WHERE discipline_id=d AND name=q.topic LIMIT 1;
    IF t IS NULL THEN
      t:=pg_temp.endo_p4_uuid('endocrinologia-topic-'||q.topic);
      INSERT INTO public.topics(id,discipline_id,name) VALUES(t,d,q.topic) ON CONFLICT(id) DO UPDATE SET name=EXCLUDED.name;
    END IF;
    qid:=pg_temp.endo_p4_uuid('endocrinologia-prova-4-q'||q.n);
    letters:=ARRAY(SELECT jsonb_array_elements_text(q.correct));
    INSERT INTO public.questions(id,discipline_id,topic_id,exam,difficulty,statement,question_type,correct_answer,correct_answers,general_comment,summary,memory_tip,trap,reference,active,image_url)
    VALUES(qid,d,t,'P4',q.difficulty,q.statement,q.type,split_part(letters[1],':',1),letters,q.general,q.summary,q.memory,q.trap,'Prova 4 de Endocrinologia — listas consolidadas, deduplicadas e revisadas em 2026.',true,NULL)
    ON CONFLICT(id) DO UPDATE SET topic_id=EXCLUDED.topic_id,exam='P4',difficulty=EXCLUDED.difficulty,statement=EXCLUDED.statement,question_type=EXCLUDED.question_type,correct_answer=EXCLUDED.correct_answer,correct_answers=EXCLUDED.correct_answers,general_comment=EXCLUDED.general_comment,summary=EXCLUDED.summary,memory_tip=EXCLUDED.memory_tip,trap=EXCLUDED.trap,reference=EXCLUDED.reference,active=true,image_url=NULL;
    FOR a IN SELECT value FROM jsonb_array_elements(q.alts) LOOP
      INSERT INTO public.alternatives(id,question_id,letter,text,explanation) VALUES(pg_temp.endo_p4_uuid(qid::text||(a->>'l')),qid,a->>'l',a->>'t',a->>'e')
      ON CONFLICT(question_id,letter) DO UPDATE SET text=EXCLUDED.text,explanation=EXCLUDED.explanation;
    END LOOP;
    DELETE FROM public.alternatives WHERE question_id=qid AND NOT(letter=ANY(ARRAY(SELECT value->>'l' FROM jsonb_array_elements(q.alts))));
  END LOOP;
END $$;

DO $$ DECLARE n integer; BEGIN
 SELECT count(*) INTO n FROM public.questions WHERE reference='Prova 4 de Endocrinologia — listas consolidadas, deduplicadas e revisadas em 2026.' AND active=true;
 IF n<>52 THEN RAISE EXCEPTION 'Payload P4 incompleto: % questões ativas',n; END IF;
 IF EXISTS(SELECT 1 FROM public.questions q WHERE q.reference='Prova 4 de Endocrinologia — listas consolidadas, deduplicadas e revisadas em 2026.' AND q.active=true AND (q.correct_answer !~ '^[A-E]$')) THEN RAISE EXCEPTION 'Questão P4 inválida'; END IF;
END $$;

COMMIT;
